        $scope.ChangeBillByMode = function (item, index) {

            var filteredArray = $filter("filter")($scope.BillPaymentByModes, { "BillPaymentTypeId": item.BillPaymentTypeId }, true);

            if (filteredArray.length > 0) {
                $scope.mainClaimObject.BillPaymentType = filteredArray[0].BillPaymentTypeName;
            }


            if ($scope.UserId == 1604 || $scope.UserId == 386 || ($scope.isIojOrgEnable && $scope.UserId == 2)) {
                $scope.GetFeeScheduleByProcedureTypes();
            } else {
                $scope.GetProcedurePayorPlanTypes();
            }
            //$scope.GetFeeScheduleByProcedureTypes();


            if ($scope.mainClaimObject.BillPaymentTypeId == 2) {
                $scope.DisableTransmitTab = true;
                var filtredobj1 = $filter("filter")($scope.AppointmentInsuranceList, { "IdentifierId": 1 });

                if (filtredobj1.length === 0) {
                    filtredobj1 = $filter("filter")($scope.AppointmentInsuranceList, { "IdentifierId": 2 });
                }

                if (filtredobj1.length > 0) {
                    $scope.mainClaimObject.PrimaryInsuranceId = filtredobj1[0].PatientInsuranceDetailId;
                    $scope.mainClaimObject.PrimaryInsuranceName = filtredobj1[0].PayorName;
                    $scope.mainClaimObject.PrimaryInsurancePlanName = filtredobj1[0].PlanName;
                    $scope.PatientClaimTransmissionObj.PatientInsuranceDetailId = filtredobj1[0].PatientInsuranceDetailId;
                    //$scope.mainClaimObject.InsuranceCoverageTypeId = filtredobj1[0].PayorTypeId || 0;
                    if (filtredobj1[0].IdentifierId == 1) {
                        $scope.mainClaimObject.CurrentResponsibilityId = 2;
                        $scope.mainClaimObject.CurrentResponsibility = "Primary Insurance";
                    } else {
                        $scope.mainClaimObject.CurrentResponsibilityId = 3;
                        $scope.mainClaimObject.CurrentResponsibility = "Secondary Insurance";
                    }
                } else {
                    alertify.error("Patient Dosent Have Insurance");
                    $scope.mainClaimObject.BillPaymentTypeId = 1;
                }

                angular.forEach($scope.mainClaimObject.PatientClaimLineItems, function (item) {
                    item.CoPaymentAmount = 0;
                    item.PatientBalance = 0;
                    item.DeductibleAmount = 0;
                    item.InsuranceBalance = item.TotalChargeAmount;
                });

            } else {
                $scope.mainClaimObject.CurrentResponsibilityId = 1;
                $scope.mainClaimObject.CurrentResponsibility = "Patient";
                $scope.DisableTransmitTab = false;
                $scope.PatientClaimTransmissionObj.PatientInsuranceDetailId = null;
                $scope.PatientClaimTransmissionObj.TransmitQueuePatientInsuranceId = null;
                $scope.mainClaimObject.TransmitQueuePatientInsuranceId = null;
                $scope.mainClaimObject.PrimaryInsuranceId = null;
                $scope.mainClaimObject.PrimaryInsuranceName = "";
                $scope.mainClaimObject.PrimaryInsurancePlanName = "";
                $scope.mainClaimObject.PrimaryInsuranceDateOfSubmission = "";
                $scope.mainClaimObject.SecondaryInsuranceId = null;
                $scope.mainClaimObject.SecondaryInsuranceName = "";
                $scope.mainClaimObject.SecondaryInsuranceDateOfSubmission = null;

                angular.forEach($scope.mainClaimObject.PatientClaimLineItems, function (item) {
                    // item.CoPaymentAmount = item.TotalChargeAmount;
                    item.DeductibleAmount = item.TotalChargeAmount;
                    item.PatientBalance = item.TotalChargeAmount;
                    item.InsuranceBalance = 0;
                });
            }
            $scope.calculateLineItemsAmount();


        }


