        $scope.AckwNumber = null;
        $scope.changeInsurancePayorClaim = function (mainObject, typeid, Iscoming) {
            if ($scope.AckwNumber != null) {
                $scope.mainClaimObject.AckNumber = $scope.AckwNumber || null;
            }

            Iscoming = Iscoming || 'OnChange';
            var patientInsuranceId = parseInt(mainObject.PatientInsuranceDetailId);

            console.log(mainObject.PayorTypeId + "__PayorTypeId");
            //$scope.mainClaimObject.InsuranceCoverageTypeId = mainObject.PayorTypeId || 0;
            $scope.mainClaimObject.InsuranceCoverageTypeId = parseInt(mainObject.InstitutionalFormId) || 1;
            typeid = typeid || 0;
            if (typeid == 1) {
                var templist = $filter("filter")($scope.AppointmentInsuranceList, { "PatientInsuranceDetailId": patientInsuranceId }, true) || [];
                if (templist.length > 0) {
                    templist[0].StatusId = templist[0].StatusId || 0;
                    if (templist[0].StatusId == 5) {
                        $scope.PatientClaimTransmissionObj.PatientInsuranceDetailId = null;
                        alertify.error("The Selected Insurance has been Inactivated");
                        return false;
                    }
                    if (templist[0].StatusId == 3) {
                        $scope.PatientClaimTransmissionObj.PatientInsuranceDetailId = null;
                        alertify.error("The selected insurance has been expired");
                        return false;
                    }
                }
            }
            if ($scope.AppointmentInsuranceList.length > 0) {
                var primaryList = $filter("filter")($scope.AppointmentInsuranceList, { IdentifierId: 1 }, true) || [];
                if (primaryList.length > 0) {
                    $scope.mainClaimObject.PrimaryInsuranceName = primaryList[0].PayorName;
                    $scope.mainClaimObject.PrimaryInsurancePlanName = primaryList[0].PlanName;
                }
            }
            if ($scope.AppointmentInsuranceList.length > 1) {
                var secondaryList = $filter("filter")($scope.AppointmentInsuranceList, { IdentifierId: 2 }, true) || [];
                if (secondaryList.length > 0) {
                    $scope.mainClaimObject.SecondaryInsuranceName = secondaryList[0].PayorName;
                    $scope.mainClaimObject.SecondaryInsurancePlanName = secondaryList[0].PlanName;
                }
            }

            $scope.PatientClaimTransmissionObj.PatientInsuranceDetailId = patientInsuranceId;
            var filtredArray = $filter("filter")($scope.AppointmentInsuranceList, { "PatientInsuranceDetailId": patientInsuranceId }, true) || [];
            if (filtredArray.length > 0) {
                $scope.PatientClaimTransmissionObj.PayorId = filtredArray[0].PayorId;
                $scope.PatientClaimTransmissionObj.PlanId = filtredArray[0].PlanId;
                $scope.PatientClaimTransmissionObj.AppointmentInsuranceDetailId = filtredArray[0].AppointmentInsuranceDetailId;
                $scope.PatientClaimTransmissionObj.OrganizationPayorId = filtredArray[0].OrganizationPayorId;
                //$scope.PatientClaimTransmissionObj.PriorAuthorizationNumber = filtredArray[0].PreAuthorizationNumber || '';

                if (Iscoming == 'OnChange') {
                    if ($scope.mainClaimObject.ClaimTypeId == 2) {
                        let FormId = parseInt(filtredArray[0].InstitutionalFormId);
                        if (FormId == 2) {
                            $scope.mainClaimObject.ClaimFormId = 2;
                            $scope.mainClaimObject.ClaimTypeId = 2;
                        } else {
                            $scope.mainClaimObject.ClaimFormId = 1;
                            $scope.mainClaimObject.ClaimTypeId = 1;
                        }
                    }
                    else {
                        $scope.mainClaimObject.ClaimFormId = 1;
                    }
                }


                if ($scope.mainClaimObject.ReferralNumber == '') {
                    $scope.mainClaimObject.ReferralNumber = filtredArray[0].ReferalReferenceNumber || '';
                }

                filtredArray[0].ReferalNPI = filtredArray[0].ReferalNPI || "";
                filtredArray[0].ReferralName = filtredArray[0].ReferralName || "";
                if (filtredArray[0].ReferralName != "") {
                    $scope.mainClaimObject.ReferringProviderObj = filtredArray[0].ReferalNPI + '-' + filtredArray[0].ReferralName;
                    $scope.mainClaimObject.ReferringProviderId = filtredArray[0].PcpReferralId;
                    $scope.mainClaimObject.ReferringProviderNPI = filtredArray[0].ReferalNPI;
                }

                $scope.PatientClaimTransmissionObj.ClaimSubmissionDate = $filter('date')($scope.CurreDate, "yyyy-MM-dd");
                //$scope.mainClaimObject.AdmissionDate = $filter('date')($scope.CurreDate, "yyyy-MM-dd");
                if ($scope.mainClaimObject.AdmissionDate == null) {
                    $scope.mainClaimObject.AdmissionDate = $filter('date')(filtredArray[0].AppointmentDate, "yyyy-MM-dd");
                }
                $scope.PatientClaimTransmissionObj.ClaimSubmissionBy = $scope.UserId;
                if ($scope.mainClaimObject.BillPaymentTypeId === 1) {
                    $scope.mainClaimObject.CurrentResponsibilityId = 1;
                    $scope.mainClaimObject.CurrentResponsibility = "Patient";
                }
                else if ($scope.mainClaimObject.PatientClaimId === 0) {
                    $scope.mainClaimObject.PrimaryInsuranceId = patientInsuranceId;
                    $scope.mainClaimObject.PrimaryInsuranceDateOfSubmission = $filter('date')($scope.CurreDate, "yyyy-MM-dd");
                    $scope.mainClaimObject.TransmitQueuePatientInsuranceId = patientInsuranceId;
                    $scope.PatientClaimTransmissionObj.InsuranceLevelId = 1;
                    $scope.PatientClaimTransmissionObj.InsuranceLevel = "P";
                    $scope.mainClaimObject.CurrentResponsibilityId = 2;
                    $scope.mainClaimObject.CurrentResponsibility = "Primary Insurance";



                } else {
                    $scope.mainClaimObject.PrimaryInsuranceId = $scope.mainClaimObject.PrimaryInsuranceId || null;
                    if ($scope.mainClaimObject.PrimaryInsuranceId === null) {
                        $scope.mainClaimObject.PrimaryInsuranceId = patientInsuranceId;
                        $scope.mainClaimObject.PrimaryInsuranceDateOfSubmission = $filter('date')($scope.CurreDate, "yyyy-MM-dd");
                        $scope.mainClaimObject.TransmitQueuePatientInsuranceId = patientInsuranceId;
                        $scope.PatientClaimTransmissionObj.InsuranceLevelId = 1;
                        $scope.PatientClaimTransmissionObj.InsuranceLevel = "P";
                        $scope.mainClaimObject.CurrentResponsibilityId = 2;
                        $scope.mainClaimObject.CurrentResponsibility = "Primary Insurance";
                    } else {

                        if ($scope.mainClaimObject.PrimaryInsuranceId === patientInsuranceId) {
                            $scope.mainClaimObject.PrimaryInsuranceId = patientInsuranceId;
                            $scope.mainClaimObject.PrimaryInsuranceDateOfSubmission = $filter('date')($scope.CurreDate, "yyyy-MM-dd");
                            $scope.mainClaimObject.TransmitQueuePatientInsuranceId = patientInsuranceId;
                            $scope.PatientClaimTransmissionObj.InsuranceLevelId = 1;
                            $scope.PatientClaimTransmissionObj.InsuranceLevel = "P";
                            $scope.mainClaimObject.CurrentResponsibilityId = 2;
                            $scope.mainClaimObject.CurrentResponsibility = "Primary Insurance";
                        } else {


                            if (!$scope.mainClaimObject.IsSecondaryInsuranceAvailable) {
                                $scope.mainClaimObject.PrimaryInsuranceId = patientInsuranceId;
                                $scope.mainClaimObject.PrimaryInsuranceDateOfSubmission = $filter('date')($scope.CurreDate, "yyyy-MM-dd");
                                $scope.mainClaimObject.TransmitQueuePatientInsuranceId = patientInsuranceId;
                                $scope.PatientClaimTransmissionObj.InsuranceLevelId = 1;
                                $scope.PatientClaimTransmissionObj.InsuranceLevel = "P";
                                $scope.mainClaimObject.CurrentResponsibilityId = 2;
                                $scope.mainClaimObject.CurrentResponsibility = "Primary Insurance";
                            } else {
                                if ($scope.mainClaimObject.SecondaryClaimInsDateOfSub == null) {
                                    $scope.mainClaimObject.AckNumber = null;
                                }

                                $scope.mainClaimObject.SecondaryInsuranceId = patientInsuranceId;
                                var SecondaryInsuranceId = $scope.mainClaimObject.SecondaryInsuranceId || 0;
                                if (SecondaryInsuranceId === 0) {
                                    $scope.PatientClaimTransmissionObj.ClaimTransmissionId = 0;
                                    $scope.PatientClaimTransmissionObj.PriorAuthorizationNumber = "";
                                    $scope.mainClaimObject.Transmit = 0;
                                }

                                $scope.mainClaimObject.SecondaryInsuranceDateOfSubmission = $filter('date')($scope.CurreDate, "yyyy-MM-dd");
                                $scope.mainClaimObject.TransmitQueuePatientInsuranceId = patientInsuranceId;
                                $scope.PatientClaimTransmissionObj.InsuranceLevelId = 2;
                                $scope.PatientClaimTransmissionObj.InsuranceLevel = "S";
                                $scope.mainClaimObject.CurrentResponsibilityId = 3;
                                $scope.mainClaimObject.CurrentResponsibility = "Secondary Insurance";
                            }

                        }

                    }

                }

            } else {
                $scope.mainClaimObject.PrimaryInsuranceId = null;
                $scope.mainClaimObject.PrimaryInsuranceDateOfSubmission = "";
                $scope.mainClaimObject.TransmitQueuePatientInsuranceId = null;
                $scope.PatientClaimTransmissionObj.InsuranceLevelId = null;
                $scope.PatientClaimTransmissionObj.InsuranceLevel = "";
                $scope.mainClaimObject.SecondaryInsuranceId = null;
                $scope.mainClaimObject.SecondaryInsuranceDateOfSubmission = null;

            }
            $scope.changePriorAuthNumber();
            if ($scope.UserId == 1604 || $scope.UserId == 386 || ($scope.isIojOrgEnable && $scope.UserId == 2)) {
                $scope.GetFeeScheduleByProcedureTypes();
            } else {
                $scope.GetProcedurePayorPlanTypes();
            }
            //$scope.GetFeeScheduleByProcedureTypes();

        };

