        $scope.changeselectDiagnosisitem = function (val, item) {

            let changeType = '';

            if (typeof val === 'string') {
                changeType = 'manual';
            } else if (typeof val === 'object' && val !== null) {
                changeType = 'typeahead-select';
            } else {
                changeType = 'autocall';
            }

            console.log('Change detected:', changeType, val);

            if (changeType === 'manual' && val.trim() === "") {
                item.DiagnosisId = 0;
                item.DiagnosisTypeId = null;
                item.ICDCode = "";
                item.DiagnosisName = "";
                item.SelectedObj = '';
            }
            if (changeType === 'autocall' && val === undefined) {
                item.SelectedObj = item.ICDCode + '-' + item.DiagnosisName;
            }
        };

        $scope.Deletediag = true;
        $scope.DeleteDiagnosis = function (item) {

            item.DiagnosisTypeId = null;
            item.ICDCode = "";
            item.DiagnosisName = "";
            item.SelectedObj = '';
            $scope.Deletediag = false;

            if ($scope.mainClaimObject.ActionType == 'SuperBill') {
                item.SuperBillDiagnosisId = item.SuperBillDiagnosisId || 0;
                if (item.SuperBillDiagnosisId != 0) {
                    var filteredarray = $filter("filter")($scope.cacheStorageItem.SuperBillDiagnosisArray, { "SuperBillDiagnosisId": item.SuperBillDiagnosisId }, true) || [];
                    if (filteredarray.length > 0) {
                        filteredarray[0].DeleteInd = "Y";
                    }
                } else {
                    var index = $scope.cacheStorageItem.SuperBillDiagnosisArray.indexOf(item);
                    if (index > -1) {
                        $scope.cacheStorageItem.SuperBillDiagnosisArray.splice(index, 1);
                    }
                }
            }

            if ($scope.mainClaimObject.PatientClaimId === 0) {

                $scope.mainClaimObject.PatientClaimLineItems.forEach(line => {

                    if (Array.isArray(line.addedDiagnosisArray)) {

                        const index = line.addedDiagnosisArray.findIndex(x => x.DiagnosisId === item.DiagnosisId);

                        if (index !== -1) {
                            line.addedDiagnosisArray.splice(index, 1);
                        }
                    }
                });
            }

            item.DiagnosisId = 0;
        }
