        $scope._restorePaidLineFinancials = function (item) {
            var snap = ($scope._paidLineFinancials || {})[item.ClaimLineItemId];
            if (!snap) return;

            // ---- 1. Restore the money posted against this line (the orphaned $50 etc.) ----
            item.PatientPaymentAmount = snap.PatientPaymentAmount;    // 50 back
            item.InsurancePaymentAmount = snap.InsurancePaymentAmount;
            item.AdjustmentAmount = snap.AdjustmentAmount;
            item.WriteOffAmount = snap.WriteOffAmount;
            item.DeductibleAmount = snap.DeductibleAmount;

            // ---- 2. Re-attach ONLY the identity of the existing insurance row (299) ----
            //         Charges must come from the NEW service, never from the snapshot.
            if (snap.ClaimInsuranceLineItems && snap.ClaimInsuranceLineItems.length) {

                if (!item.ClaimInsuranceLineItems || !item.ClaimInsuranceLineItems.length) {
                    // new service left no insurance line -> rebuild from old identity + NEW charges
                    item.ClaimInsuranceLineItems = snap.ClaimInsuranceLineItems.map(function (old) {
                        return {
                            ClaimLineItemInsuranceId: old.ClaimLineItemInsuranceId,        // 299  (keep)
                            ClaimLineItemId: item.ClaimLineItemId,
                            PatientClaimId: old.PatientClaimId,
                            PatientInsuranceDetailId: old.PatientInsuranceDetailId,        // 5109 (keep)
                            InsuranceIdentifierId: old.InsuranceIdentifierId,           // 1    (keep)
                            UnitCharge: parseFloat(item.UnitCharge) || 0,        // NEW
                            Quantity: parseFloat(item.Quantity) || 1,          // NEW
                            TotalChargeAmount: parseFloat(item.TotalChargeAmount) || 0, // NEW
                            DeleteInd: "N"
                        };
                    });
                } else {
                    // new service already built fresh insurance lines -> just stamp the old id back
                    angular.forEach(item.ClaimInsuranceLineItems, function (pitem) {
                        var match = snap.ClaimInsuranceLineItems.filter(function (o) {
                            return o.InsuranceIdentifierId === pitem.InsuranceIdentifierId
                                && o.PatientInsuranceDetailId === pitem.PatientInsuranceDetailId;
                        })[0] || snap.ClaimInsuranceLineItems[0];

                        if (match) {
                            pitem.ClaimLineItemInsuranceId = match.ClaimLineItemInsuranceId; // 299
                            pitem.DeleteInd = "N";
                        }
                        // DO NOT touch pitem.UnitCharge / Quantity / TotalChargeAmount -> keep new charge
                    });
                }
            }

            // ---- 3. Net the prior payment against the responsibility typed into "Pat. Bal" ----
            var enteredResponsibility = parseFloat(item.PatientBalance) || 0;   // biller types 50
            item.PatientResponsibilityAmount = enteredResponsibility;
            item.PatientBalance = Math.max(
                enteredResponsibility - snap.PatientPaymentAmount,             // 50 - 50
                0
            ).toFixed(2);                                                      // -> "0.00"
        };



