        $scope.deleteClaimLineItem = function (index, item, skipConfirm) {

            function doDelete() {
                if (item.ClaimLineItemId != 0) {
                    item.DeleteInd = "Y";
                    angular.forEach(item.ClaimInsuranceLineItems, function (pitem) {
                        pitem.DeleteInd = "Y";
                    });
                } else {
                    $scope.mainClaimObject.PatientClaimLineItems.splice(index, 1);
                }
                $scope.calculateLineItemsAmount();
            }

            if (skipConfirm) {

                doDelete();
                return;
            }

            alertify.confirm("<b class='txt-centre'>Confirm!</b><h4 class='txt-body-centre'>Are you sure you want to delete ? </h4>", function () {
                doDelete();
                $scope.$apply();
            }, function () {
            });
        };
