            $scope.mainClaimObject.BranchServiceLocationId = data.rows[0].BranchServiceLocationId || 0;
            $scope.mainClaimObject.PatientClaimId = data.rows[0].PatientClaimId || 0;
            $scope.mainClaimObject.PatientClaimNumber = data.rows[0].PatientClaimNumber || "";
            $scope.mainClaimObject.PatientId = data.rows[0].PatientId || 0;
            $scope.mainClaimObject.AppointmentId = $scope.cacheStorageItem.appointmentid || 0;
