            $scope.mainClaimObject.PlaceOfServiceName = data.rows[0].PlaceOfServiceName || "";
            $scope.mainClaimObject.LocationAddressId = data.rows[0].LocationAddressId || null;
            $scope.mainClaimObject.BillPaymentTypeId = data.rows[0].BillPaymentTypeId || "";
            $scope.mainClaimObject.BillPaymentType = data.rows[0].BillPaymentType || "";
            $scope.mainClaimObject.BillPaymentTypeObj = data.rows[0].BillPaymentTypeObj || "";
            $scope.mainClaimObject.BillingProviderId = data.rows[0].BillingProviderId || null;
