            $scope.mainClaimObject.IsReadytosubmit = data.rows[0].IsReadytosubmit || false;
            $scope.mainClaimObject.ReferringProvider = data.rows[0].ReferringProvider || "";
            $scope.mainClaimObject.ReferringProviderFirstName = data.rows[0].ReferringProviderFirstName || "";
