        $scope.SaveSuperBill = function (RespId) {

            RespId = RespId || 0;
            console.log($scope.mainClaimObject.PatientClaimLineItems);
            $scope.SuperBillArray = [];
            $scope.SuperBillDiagnosisArray = [];
            let diagiCount = 0; let servicesCode = 0; let RespCount = 0; let DOSfrom = 0;
            if ($scope.mainClaimObject.PatientClaimLineItems.length > 0) {
                angular.forEach($scope.mainClaimObject.PatientClaimLineItems, function (item, index) {
                    item.ServiceId = item.ServiceId || 0;
                    if (item.DeleteInd == "N" && item.ServiceId != 0) {
                        var filteredarray = $filter("filter")(item.addedDiagnosisArray, { "IsSelected": true }) || [];
                        if (filteredarray.length == 0) {
                            diagiCount++;
                        }

                        item.ServiceCode = item.ServiceCode || "";
                        item.DOSfrom = item.DOSfrom || "";
                        if (item.ServiceCode == "") {
                            servicesCode++;
                        }
                        if (item.DOSfrom == "") {
                            DOSfrom++;
                        }


                    }
                    let SuperModifierList = [];
                    if (item.ServiceId != 0) {

                        const modifiers = [item.Modifier1, item.Modifier2, item.Modifier3, item.Modifier4];
                        modifiers.forEach(modCode => {
                            if (modCode) {
                                const found = $filter('filter')($scope.masterModifierList, { ModifierCode: modCode }) || [];
                                if (found.length) {
                                    SuperModifierList.push(found[0]);
                                }
                            }
                        });

                        let filterDiagnosisArray = [];

                        $scope.cacheStorageItem.SuperBillDiagnosisArray = $scope.cacheStorageItem.SuperBillDiagnosisArray || [];
                        if ($scope.cacheStorageItem.SuperBillDiagnosisArray.length > 0) {
                            if (item.DiagnosisList.length > 0) {
                                angular.forEach(item.DiagnosisList, function (ditem, index) {

                                    var obj = {
                                        "SortOrder": index + 1,
                                        "SuperbillItemDiagnosisId": ditem.SuperbillItemDiagnosisId || 0,
                                        "DiagnosisId": ditem.DiagnosisId,
                                        "DiagnosisName": ditem.DiagnosisName,
                                        "DiagnosisNotes": "",
                                        "DiagnosisCode": ditem.ICDCode,
                                        "ICD10Code": ditem.ICDCode,
                                        "FullName": ditem.ICDCode + '-' + ditem.DiagnosisName,
                                        "HospitalId": $scope.mainClaimObject.OrganizationId,
                                        "UserId": $scope.UserId,
                                        "Type": ditem.Type,
                                        "DeleteInd": ditem.DeleteInd || "N"
                                    }
                                    filterDiagnosisArray.push(obj);
                                });
                            }

                            if (item.addedDiagnosisArray.length > 0) {
                                angular.forEach(item.addedDiagnosisArray, function (aitem) {
                                    var obj = {
                                        "SuperBillDiagnosisId": aitem.SuperBillDiagnosisId || 0,
                                        "DiagnosisId": aitem.DiagnosisId,
                                        "DiagnosisName": aitem.DiagnosisName,
                                        "DiagnosisNotes": "",
                                        "DiagnosisCode": aitem.ICDCode,
                                        "ICD10Code": aitem.ICDCode,
                                        "FullName": aitem.ICDCode + '-' + aitem.DiagnosisName,
                                        "HospitalId": $scope.mainClaimObject.OrganizationId,
                                        "UserId": $scope.UserId,
                                        "Type": aitem.Type,
                                        "DeleteInd": "N"
                                    }

                                    var exists = $scope.SuperBillDiagnosisArray.some(function (existingItem) {
                                        return existingItem.DiagnosisId === aitem.DiagnosisId;
                                    });

                                    if (!exists) {
                                        $scope.SuperBillDiagnosisArray.push(obj);
                                    }

                                });

                                angular.forEach($scope.cacheStorageItem.SuperBillDiagnosisArray, function (item) {
                                    item.SuperBillDiagnosisId = item.SuperBillDiagnosisId || 0;
                                    if (item.SuperBillDiagnosisId != 0) {
                                        var filteredarray = $filter("filter")($scope.SuperBillDiagnosisArray, { "SuperBillDiagnosisId": item.SuperBillDiagnosisId }) || [];
                                        if (filteredarray.length === 0) {
                                            item.DeleteInd = "Y";
                                            $scope.SuperBillDiagnosisArray.push(item);
                                        }
                                    }
                                });
                            }

                        } else {
                            if (item.DiagnosisList.length > 0) {
                                angular.forEach(item.DiagnosisList, function (ditem, index) {
                                    var obj = {
                                        "SortOrder": index + 1,
                                        "SuperbillItemDiagnosisId": ditem.SuperbillItemDiagnosisId || 0,
                                        "DiagnosisId": ditem.DiagnosisId,
                                        "DiagnosisName": ditem.DiagnosisName,
                                        "DiagnosisNotes": "",
                                        "DiagnosisCode": ditem.ICDCode,
                                        "ICD10Code": ditem.ICDCode,
                                        "FullName": ditem.ICDCode + '-' + ditem.DiagnosisName,
                                        "HospitalId": $scope.mainClaimObject.OrganizationId,
                                        "UserId": $scope.UserId,
                                        "Type": ditem.Type,
                                        "DeleteInd": ditem.DeleteInd || "N"
                                    }
                                    filterDiagnosisArray.push(obj);
                                });
                            }

                            if ($scope.SuperBillDiagnosisArray.length === 0) {
                                angular.forEach(item.addedDiagnosisArray, function (aitem) {
                                    var obj = {
                                        "SuperBillDiagnosisId": 0,
                                        "DiagnosisId": aitem.DiagnosisId,
                                        "DiagnosisName": aitem.DiagnosisName,
                                        "DiagnosisNotes": "",
                                        "DiagnosisCode": aitem.ICDCode,
                                        "ICD10Code": aitem.ICDCode,
                                        "FullName": aitem.ICDCode + '-' + aitem.DiagnosisName,
                                        "HospitalId": $scope.mainClaimObject.OrganizationId,
                                        "UserId": $scope.UserId,
                                        "Type": aitem.Type,
                                        "DeleteInd": "N"
                                    }
                                    $scope.SuperBillDiagnosisArray.push(obj);
                                });
                            }
                        }

                        if (item.ResponcibilityId === 0) {
                            RespCount++;
                        }

                        let activeIndex = 1;
                        if (filterDiagnosisArray.length > 0) {
                            filterDiagnosisArray.forEach(d => {
                                d.SortOrder = d.DeleteInd === "N" ? activeIndex++ : null;
                            });
                        }


                        let billobj = {
                            "DragCPTOrder": index + 1,
                            "SuperBillItemId": item.SuperBillItemId || 0,
                            "SuperBillId": item.SuperBillId || 0,
                            "DateOfService": item.DOSfrom,
                            "AppointmentId": $scope.cacheStorageItem.appointmentid,
                            "IsBillSelected": item.IsBillSelected,
                            "IsBillingDone": item.IsBillingDone,
                            "IsDiagnosis": item.IsDiagnosis,
                            "CPTCode": item.ServiceCode || "",
                            "Quantity": item.Quantity || null,
                            "Cost": item.UnitCharge || 0,
                            "OrganizationProcedureId": item.OrganizationProcedureId,
                            "ProcedureId": item.ServiceId,
                            "OrganizationId": $scope.mainClaimObject.OrganizationId,
                            "TypeOfServiceId": item.TypeOfServiceId,
                            "ProcedureCode": item.ServiceObj,
                            "ProcedureName": item.ServiceName,
                            "DeleteInd": item.DeleteInd || 'N',
                            "OrganId": item.OrganId,
                            "ResponcibilityId": item.ResponcibilityId || 0,
                            "DiagnosisArray": filterDiagnosisArray || [],
                            "Modifiers": SuperModifierList || [],
                            "MedicineId": item.MedicineId || '',
                            "MedicineName": item.MedicineName || '',
                            "MedicineStrength": item.MedicineStrength || '',
                            "DrugNDCID": item.DrugNDCID || '',
                            "UnitId": item.UnitId || '',
                            "UnitName": item.UnitName || '',
                            "SortOrder": index + 1,


                        }
                        $scope.SuperBillArray.push(billobj);
                    }



                });

            }

            if ($scope.SuperBillArray.length == 0) {
                alertify.error("Please Add atleast one Service");
                return false;
            }
            if (DOSfrom > 0) {
                alertify.error("Please select DOS");
                return false;
            }
            if (servicesCode > 0) {
                alertify.error("Please select CPT code");
                return false;
            }

            if (diagiCount > 0) {
                alertify.error("Please map the diagnosis");
                return false;
            }

            if (RespCount > 0) {
                alertify.error("Please select claim responsibility");
                return false;
            }

            let reqObj = {
                "UserId": $scope.UserId,
                "AppointmentId": $scope.cacheStorageItem.appointmentid,
                "OrganizationId": $scope.mainClaimObject.OrganizationId,
                "SuperBillRemarks": $scope.cacheStorageItem.SuperBillRemarks || "",
                "VisitId": $scope.mainClaimObject.VisitId || 0,
                "EncounterStatus": $scope.mainClaimObject.EncounterStatus || "",
                "EncounterStatusId": $scope.mainClaimObject.EncounterStatusId || 0,
                "SuperBillId": $scope.mainClaimObject.SuperBillId || 0,
                "SuperBillArray": $scope.SuperBillArray || [],
                "SuperBillDiagnosisArray": $scope.SuperBillDiagnosisArray || [],
                "Logs": {},
                "DeleteInd": "N"
            }


            /* Encounter Log Details*/

            function areServiceLinesDifferent(newArray, oldArray) {
                if ((!newArray && oldArray) || (newArray && !oldArray)) return true;
                if (!newArray && !oldArray) return false;

                const filteredNew = newArray.filter(item => item.ServiceId !== 0);
                if (filteredNew.length !== oldArray.length) return true;

                const sortedNew = filteredNew.slice().sort((a, b) => (a.SuperBillItemId || 0) - (b.SuperBillItemId || 0));
                const sortedOld = oldArray.slice().sort((a, b) => (a.SuperBillItemId || 0) - (b.SuperBillItemId || 0));

                for (let i = 0; i < sortedNew.length; i++) {
                    const newItem = sortedNew[i];
                    const oldItem = sortedOld[i];

                    if (newItem.SuperBillItemId !== oldItem.SuperBillItemId ||
                        newItem.ServiceId !== oldItem.ServiceId ||
                        newItem.DeleteInd !== oldItem.DeleteInd ||
                        newItem.ServiceCode !== oldItem.ServiceCode ||
                        newItem.Quantity !== oldItem.Quantity ||
                        newItem.UnitCharge !== oldItem.UnitCharge) {
                        return true;
                    }

                }
                return false;
            }

            const serviceLinesDifferent = areServiceLinesDifferent($scope.mainClaimObject.PatientClaimLineItems, $scope.LogObj.oldPatientClaimLineItems);


            function areDiagnosesDifferent(newArray, oldArray) {
                if ((!newArray && oldArray) || (newArray && !oldArray)) return true;
                if (!newArray && !oldArray) return false;

                if (newArray.length !== oldArray.length) return true;

                const sortedNew = newArray.slice().sort((a, b) => a.DiagnosisId - b.DiagnosisId);
                const sortedOld = oldArray.slice().sort((a, b) => a.DiagnosisId - b.DiagnosisId);

                for (let i = 0; i < sortedNew.length; i++) {
                    const newDiag = sortedNew[i];
                    const oldDiag = sortedOld[i];

                    if (typeof oldDiag.DeleteInd === "boolean") {
                        oldDiag.DeleteInd = oldDiag.DeleteInd ?? false;
                        oldDiag.DeleteInd = oldDiag.DeleteInd === true ? "Y" : "N";
                    }

                    if (newDiag.DiagnosisId !== oldDiag.DiagnosisId || newDiag.DeleteInd !== oldDiag.DeleteInd) {
                        return true;
                    }
                }
                return false;
            }

            const isDiagDifferent = areDiagnosesDifferent($scope.SuperBillDiagnosisArray, $scope.cacheStorageItem.SuperBillDiagnosisArray);


            function formatResponsibility(id) {
                const map = {
                    1: "Patient Office",
                    2: "Insurance-Professional",
                    3: "Insurance-Institutional",
                    4: "Worker comp",
                    5: "Others",
                    6: "Patient ASC"
                };
                return map[id] || "";
            }

            function createLog(subModuleId, screenType, actionType, newDesc, oldDesc) {
                return {
                    "LogId": 0,
                    "ModuleId": 6,
                    "ModuleName": "Billing",
                    "SubModuleId": subModuleId,
                    "AppointmentId": $scope.cacheStorageItem.appointmentid,
                    "SubModuleName": "Encounters",
                    "ScreenType": screenType,
                    "ActionType": actionType,
                    "OldActionDescription": oldDesc || "",
                    "NewActionDescription": newDesc,
                    "Status": "Success",
                    "Remarks": "",
                    "ActionDateTime": $filter("date")(new Date(), "yyyy-MM-dd HH:mm:ss")
                };
            }

            if ($scope.SuperBillDiagnosisArray?.length) {
                let actionType = $scope.mainClaimObject.SuperBillId === 0 ? "Added" : "Edited";

                let newDescArray = $scope.SuperBillDiagnosisArray
                    .filter(x => x.DeleteInd === "N")
                    .map((x, i) => `${i + 1}. ${x.Type}: ${x.FullName}`);

                let newDesc = newDescArray.join('\n');

                if (newDescArray.length) {
                    $scope.LogObj.LogArray.push(createLog(38, "Diagnosis", actionType, newDesc, ""));
                }

                let newDelDescArray = $scope.SuperBillDiagnosisArray
                    .filter(x => x.DeleteInd === "Y")
                    .map((x, i) => `${i + 1}. ${x.Type}: ${x.FullName}`);

                let newDelDesc = newDelDescArray.join('\n');

                if (newDelDescArray.length) {
                    $scope.LogObj.LogArray.push(createLog(38, "Diagnosis", "Deleted", newDelDesc, ""));
                }
            }

            if (isDiagDifferent) {
                let actionType = $scope.mainClaimObject.SuperBillId === 0 ? "Added" : "Edited";

                let oldDescArray = $scope.cacheStorageItem.SuperBillDiagnosisArray
                    .filter(x => x.DeleteInd === false)
                    .map((x, i) => `${i + 1}. ${x.Type}: ${x.FullName}`);

                let oldDesc = oldDescArray.join('\n');

                if (oldDescArray.length) {
                    $scope.LogObj.LogArray.push(createLog(38, "Diagnosis", actionType, "", oldDesc));
                }

                let oldDelDescArray = $scope.cacheStorageItem.SuperBillDiagnosisArray
                    .filter(x => x.DeleteInd === true)
                    .map((x, i) => `${i + 1}. ${x.Type}: ${x.FullName}`);

                let oldDelDesc = oldDelDescArray.join('\n');

                if (oldDelDescArray.length) {
                    $scope.LogObj.LogArray.push(createLog(38, "Diagnosis", "Deleted", "", oldDelDesc));
                }
            }

            if ($scope.mainClaimObject.PatientClaimLineItems?.length) {
                let actionType = "Edited";

                let newDescArray = $scope.mainClaimObject.PatientClaimLineItems
                    .filter(x => x.DeleteInd === "N" && x.ServiceCode)
                    .map((item, i) => {
                        actionType = item.SuperBillItemId === 0 ? "Added" : "Edited";
                        let parts = [
                            `DOS:${item.DOSfrom}`, item.ServiceCode ? `Service:${item.ServiceCode} - ${item.ServiceName}` : null, item.DiagnosisPointers ? `DiagnosisPointers:${item.DiagnosisPointers}` : null,
                            (item.ModifierCode1 || item.ModifierCode2 || item.ModifierCode3 || item.ModifierCode4) ? `Modifiers:${[item.ModifierCode1, item.ModifierCode2, item.ModifierCode3, item.ModifierCode4].filter(Boolean).join(", ")}` : null,
                            item.Quantity ? `Units:${item.Quantity}` : null, item.UnitCharge ? `Unit Cost:${item.UnitCharge}` : null,
                            item.TotalChargeAmount ? `Total Charge:${item.TotalChargeAmount}` : null, item.ResponcibilityId ? `Claim Responsibility:${formatResponsibility(item.ResponcibilityId)}` : null
                        ];

                        let desc = `${i + 1}. ` + parts.filter(Boolean).join(", ");
                        return desc;
                    });

                let newDescServiceLine = newDescArray.join('\n');
                if (newDescArray.length) {
                    $scope.LogObj.LogArray.push(createLog(38, "Service Line", actionType, newDescServiceLine));
                }

                let newDescdltArray = $scope.mainClaimObject.PatientClaimLineItems
                    .filter(x => x.DeleteInd === 'Y')
                    .map((item, i) => {
                        let parts = [
                            item.ServiceCode ? `Service:${item.ServiceCode} - ${item.ServiceName}` : null,
                        ];

                        let desc = `${i + 1}. ` + parts.filter(Boolean).join(", ");
                        return desc;
                    });

                let newDescdltServiceLine = newDescdltArray.join('\n');
                if (newDescdltArray.length) {
                    $scope.LogObj.LogArray.push(createLog(38, "Service Line", "Deleted", newDescdltServiceLine));
                }
            }

            if (serviceLinesDifferent) {
                let actionType = "Edited";

                let oldDescArray = $scope.LogObj.oldPatientClaimLineItems
                    .filter(x => x.DeleteInd === "N" && x.ServiceCode)
                    .map((item, i) => {
                        actionType = item.SuperBillItemId === 0 ? "Added" : "Edited";
                        let parts = [
                            `DOS:${item.DOSfrom}`, item.ServiceCode ? `Service:${item.ServiceCode} - ${item.ServiceName}` : null, item.DiagnosisPointers ? `DiagnosisPointers:${item.DiagnosisPointers}` : null,
                            (item.ModifierCode1 || item.ModifierCode2 || item.ModifierCode3 || item.ModifierCode4) ? `Modifiers:${[item.ModifierCode1, item.ModifierCode2, item.ModifierCode3, item.ModifierCode4].filter(Boolean).join(", ")}` : null,
                            item.Quantity ? `Units:${item.Quantity}` : null, item.UnitCharge ? `Unit Cost:${item.UnitCharge}` : null,
                            item.TotalChargeAmount ? `Total Charge:${item.TotalChargeAmount}` : null, item.ResponcibilityId ? `Claim Responsibility:${formatResponsibility(item.ResponcibilityId)}` : null
                        ];

                        let desc = `${i + 1}. ` + parts.filter(Boolean).join(", ");
                        return desc;
                    });

                let oldDescServiceLine = oldDescArray.join('\n');
                if (oldDescArray.length) {
                    $scope.LogObj.LogArray.push(createLog(38, "Service Line", actionType, "", oldDescServiceLine));
                }

                let oldDescdltArray = $scope.LogObj.oldPatientClaimLineItems
                    .filter(x => x.DeleteInd === 'Y')
                    .map((item, i) => {
                        let parts = [
                            item.ServiceCode ? `Service:${item.ServiceCode} - ${item.ServiceName}` : null,
                        ];

                        let desc = `${i + 1}. ` + parts.filter(Boolean).join(", ");
                        return desc;
                    });

                let oldDescdltServiceLine = oldDescdltArray.join('\n');
                if (oldDescdltArray.length) {
                    $scope.LogObj.LogArray.push(createLog(38, "Service Line", "Deleted", "", oldDescdltServiceLine));
                }
            }

            if ($scope.LogObj.LogArray?.length) {
                reqObj.Logs = $scope.LogObj;
            }


            eHnoteDiagnosisDataServices.AddupdateSuperBill(reqObj).then(function (resp) {
                if (resp.data.Status === "Success") {
                    alertify.success("Successfully Validated!");
                    if ($scope.claimScreenParentObj.ScreenType == 'Popup') {
                        $scope.$emit("AddUpdateClaim", { action: 'save', values: { key1: 0 } });
                    } else if ($scope.claimScreenParentObj.ScreenType == 'saveandcreate') {
                        $scope.$emit("AddUpdateClaim", { action: 'saveandcreate', values: { key1: RespId } });
                    } else {
                        $scope.init();
                    }

                }
            }, function (err) {
                alertify.error("Fetching data failed!");

            });
        }


