        $scope.navtoOpenAddDepositAmount = function (type, Incomingfrom, ID) {

            $scope.ClaimDetails = $scope.ClaimDetails || null;
            if ($scope.ClaimDetails != null) {
                $scope.BillingProviderName = $scope.ClaimDetails.BillingProviderName || "";
                $scope.FacilityName = $scope.ClaimDetails.FacilityName || "";
            }

            if (Incomingfrom == 'AddClaim') {
                if (!$scope.isIojOrgEnable) {
                    $scope.mainClaimObject.PrimaryProviderId = $scope.mainClaimObject.PrimaryProviderId || null;
                    if ($scope.mainClaimObject.PrimaryProviderId == null) {
                        alertify.error("Please select Primary Provider");
                        return false;
                    }
                }
                let diagiCount = 0; let servicesCode = 0; let PriorAuthNo = 0;
                if ($scope.mainClaimObject.PatientClaimLineItems.length > 0) {
                    angular.forEach($scope.mainClaimObject.PatientClaimLineItems, function (item) {
                        item.ServiceId = item.ServiceId || 0;
                        if (item.DeleteInd == "N" && item.ServiceId != 0) {
                            var filteredarray = $filter("filter")(item.addedDiagnosisArray, { "IsSelected": true }) || [];
                            if (filteredarray.length == 0) {
                                diagiCount++;
                            }

                            item.ServiceCode = item.ServiceCode || "";
                            if (item.ServiceCode == "") {
                                servicesCode++;
                            }
                        }
                        else if (item.ServiceId == 0) {
                            item.UnitCharge = item.UnitCharge || 0;
                            if ((item.UnitCharge !== 0) || ((item.Modifier1 != null && item.Modifier1 != "") || (item.Modifier2 != null && item.Modifier2 != "") || (item.Modifier3 != null && item.Modifier3 != "") || (item.Modifier4 != null && item.Modifier4 != ""))) {
                                servicesCode++;
                            }
                        }
                    });
                }

                if (PriorAuthNo > 0) {
                    alertify.error("Prior Auth No. is Mandatory ");
                    return false;
                }

                if (servicesCode > 0) {
                    alertify.error("Please select CPT code");
                    return false;
                }

                if (diagiCount > 0) {
                    alertify.error("Please map the diagnosis");
                    return false;
                }


                $scope.mainClaimObject.ClaimTypeId = $scope.mainClaimObject.ClaimTypeId || "";
                if ($scope.mainClaimObject.ClaimTypeId == "") {
                    alertify.error("please select Professional or Institutional");
                    return false;
                }
                $scope.mainClaimObject.ReferringProviderObj = $scope.mainClaimObject.ReferringProviderObj || null;
                $scope.mainClaimObject.ReferringProviderNPI = $scope.mainClaimObject.ReferringProviderNPI || "";
                if ($scope.mainClaimObject.ReferringProviderNPI === "" && $scope.mainClaimObject.ReferringProviderObj != null) {
                    alertify.error("The selected Referral Provider does not have an NPI number.");
                    return false;
                }


                var filteredServices = $filter("filter")($scope.mainClaimObject.PatientClaimLineItems, function (item) {
                    return item.ServiceId !== 0 && item.DeleteInd !== "Y";
                });
                if (filteredServices.length === 0) {
                    alertify.error("Please Add atleast one Service");
                    return false;
                }


                if ($scope.AppointmentInsuranceList.length > 0 && $scope.mainClaimObject.CurrentResponsibilityId != 1) {
                    if ($scope.PatientClaimTransmissionObj.PatientInsuranceDetailId != null) {
                        var templist = $filter("filter")($scope.AppointmentInsuranceList, { "PatientInsuranceDetailId": $scope.PatientClaimTransmissionObj.PatientInsuranceDetailId }, true) || [];
                        if (templist.length > 0) {
                            templist[0].StatusId = templist[0].StatusId || 0;
                            if (templist[0].StatusId == 5) {
                                $scope.PatientClaimTransmissionObj.PatientInsuranceDetailId = null;
                                alertify.error("The selected insurance has been Inactivated");
                                return false;
                            }
                            if (templist[0].StatusId == 3) {
                                $scope.PatientClaimTransmissionObj.PatientInsuranceDetailId = null;
                                alertify.error("The selected insurance has been expired");
                                return false;
                            }
                        }
                    } else {
                        alertify.error("Please select the payor name");
                        return false;
                    }
                }


            }

            $scope.obj = {
                "PatientId": $scope.cacheStorageItem.PatientID,
                "ScreenType": type || '',
                "Incomingfrom": Incomingfrom || '',
                "Type": '',
                "UsersList": $scope.allUserList,
                "Patientobj": $scope.Patientobj,
                "ClaimDetailsList": $scope.ClaimDetailsList,
                "OrganizationFacilityList": $scope.OrganizationFacilityList,
                "DepositTypes": $scope.DepositTypes,
                "WriteOffReasons": $scope.WriteOffReasons,
                "BillingProviderName": $scope.BillingProviderName || "",
                "FacilityName": $scope.FacilityName || "",
                "HospitalId": $scope.HospitalId || "",
                "TotalPatientBalance": $scope.mainClaimObject.TotalPatientBalance || 0,
                "AllBranchesList": $scope.mainBillerDataObj.AllBranchesList || [],
                "HospitalId": $scope.HospitalId,
                "ID": ID || 2,
                "PatientClaimId": $scope.mainClaimObject.PatientClaimId || null,
                "CardTypesData": $scope.CardTypesData || null,
                "ClaimDataObj": $scope.mainClaimObject || {},
                "DiagnosisArrayList": $scope.addedDiagnosisArray || [],
                "PatientClaimTransmissionObj": $scope.PatientClaimTransmissionObj || {},
                "ClaimSaveSatus": Incomingfrom || '',
                "mainBillerDataObj": $scope.mainBillerDataObj || {},
                "DoctorName": $scope.mainClaimObject.VisitDoctorObj.FullName || ""
            }

            type = type || 0;
            if (type === 'Payment') {
                if ($scope.ClaimDetails != null) {
                    $scope.obj.PatientClaimNumber = $scope.ClaimDetails.PatientClaimNumber || "";
                }
                if ($scope.mainClaimObject.PatientClaimId === 0) {
                    $scope.SavePatientEncounterClaim('Ready', 1, 'navPaymentpopup', 2, ID);
                    return false;
                }
                if ($scope.ClaimSaveTypeId === 'SaveClaim') {
                    $scope.SavePatientEncounterClaim('Ready', 1, 'navPaymentpopup', 2, ID);
                    return false;
                }
                //if (Incomingfrom === 'AddClaim') {
                //    $scope.SavePatientEncounterClaim('Ready', 1, 'navPaymentpopup', 2, ID);
                //    return false;
                //}

                $scope.navtoDepositpaymentpopup($scope.obj, type, Incomingfrom, ID);
            }

            if (type == 'Deposit') {
                if ($scope.mainClaimObject.PatientClaimId == 0) {
                    alertify.confirm("<b class='txt-centre'>Confirm!</b><h4 class='txt-body-centre'>To add a deposit, you need to save the claim. Do you want to save the claim and continue?</h4>", function () {
                        $scope.SavePatientEncounterClaim('Ready', 1, 'navDepositpopup', 2, ID);
                        return false;

                    }, function () {

                    });
                } else {
                    $scope.navtoDepositpaymentpopup($scope.obj, type, Incomingfrom, ID);
                }
            }

        }

        $scope.navtoDepositpaymentpopup = function (obj, type, Incomingfrom, ID) {

            $scope.obj = obj || {};
            $scope.obj.isIojOrgEnable = $scope.isIojOrgEnable || false;
            var modalInstance = $uibModal.open({
                "templateUrl": "templates/UsClaims/AddPatientDepositPopup.html",
                "controller": "UsAddPatientDepositsCtrl",
                "resolve": {
                    "Selectobj": function () { return $scope.obj; },
                },
                //"size": "lg",
                "backdrop": "static",
                "keyboard": false,
                "windowClass": "modal__popup--1  "

            });
            modalInstance.result.then(function (resp) {
                //$scope.SearchPatientDepositsObj = angular.copy($scope.GetPatientDepositsLitsObj());
                /*$scope.SearchPatientDepositslist("pageLoad");*/
                console.log(ID);
                if (resp != undefined) {
                    $scope.PatientAlertobj.IsAlertInd = resp.IsAlertInd || false;
                }

                $scope.getPatientDepositAmountById();
                if ($scope.mainClaimObject.PatientClaimId != 0) {
                    $scope.claimScreenParentObj.PatientClaimId = $scope.mainClaimObject.PatientClaimId;
                    $scope.GetClaimDetails();
                }
                if (ID == 1) {
                    if ($scope.mainClaimObject.PatientClaimId != 0) {
                        $scope.SubTab = 1;
                        var pobj = {
                            "PatientClaimId": $scope.mainClaimObject.PatientClaimId
                        }
                        $scope.GetPatientClaimDetailsById(pobj);
                    }
                } else {
                    if ($scope.mainClaimObject.PatientClaimId != 0) {
                        var pobj = {
                            "PatientClaimId": $scope.mainClaimObject.PatientClaimId
                        }
                        $scope.GetPatientClaimDetailsById(pobj);
                    }
                }
                if (Incomingfrom == 'AddClaim') {
                    /*$scope.BillingPopUpClose();*/

                    $scope.SubTab = 2;
                }
            }, function () { });
        }



        //$rootScope.$on('navtoOpenAddDepositAmount', function (data) {
        //    debugger;
        //    $scope.navtoOpenAddDepositAmount(0);
        //});
        $scope.addClaimLineItem = function (item, typeid) {

            var lineitemarray = $filter("filter")($scope.mainClaimObject.PatientClaimLineItems, { "ServiceCode": "", "DeleteInd": "N" }, true) || [];
            if (lineitemarray.length > 0) {
                alertify.error("Please select CPT code");
                return false;
            }

            let i = 0;
            angular.forEach($scope.mainClaimObject.PatientClaimLineItems, function (item) {
                if (item.DeleteInd == "N") {
                    var filteredarray = $filter("filter")(item.addedDiagnosisArray, { "IsSelected": true }, true) || [];
                    if (filteredarray.length == 0) {
                        i++;
                    }
                }
            });


            if (i > 0) {
                alertify.error("Please map the diagnosis");
                return false;
            }

            //if (typeid == 1) {
            //    var temparray = $filter("filter")($scope.mainClaimObject.PatientClaimLineItems, { "UnitCharge": 0, "DeleteInd": "N" }, true) || [];
            //    if (temparray.length > 0) {
            //        alertify.error("Please enter unit charge");
            //        return false;
            //    }
            //}

            var emptyfilteredarray = $filter("filter")($scope.mainClaimObject.PatientClaimLineItems, { "ServiceCode": "" }, true) || [];
            if (emptyfilteredarray.length == 0) {
                var newClaimLineitemObj = $scope.GetClaimLineItemObj();
                newClaimLineitemObj.addedDiagnosisArray = angular.copy($scope.addedDiagnosisArray);
                newClaimLineitemObj.PlaceOfServiceId = $scope.mainClaimObject.PlaceOfServiceId;
                // newClaimLineitemObj.DOSfrom = moment().format("MM-DD-YYYY");
                newClaimLineitemObj.DOSfrom = $filter("date")($scope.mainClaimObject.AdmissionDate, "MM-dd-yyyy");
                $scope.mainClaimObject.PatientClaimLineItems.push(newClaimLineitemObj);
            }
        }


        $scope.navtoOpenPopupDetails = function (item, id, NotesId) {

            let AppointmentId = null;
            let PatientId = null;

            if ($scope.claimScreenParentObj) {
                if ($scope.claimScreenParentObj.AppointmentId == null) {
                    AppointmentId = $scope.cacheStorageItem.appointmentid;
                    PatientId = $scope.cacheStorageItem.PatientID;
                } else {
                    AppointmentId = $scope.claimScreenParentObj.AppointmentId;
                    PatientId = $scope.claimScreenParentObj.PatientId;
                }
                $scope.claimScreenParentObj.AppointmentTypeId = $scope.claimScreenParentObj.AppointmentTypeId || null;
                if ($scope.claimScreenParentObj.AppointmentTypeId == null) {
                    $scope.claimScreenParentObj.AppointmentTypeId = $scope.PatientAppointmentTypeId.AppointmentTypeId != null ? $scope.PatientAppointmentTypeId.AppointmentTypeId : null;

                } else {
                    $scope.claimScreenParentObj.AppointmentTypeId = $scope.claimScreenParentObj.AppointmentTypeId || null;
                }
            }

            $scope.IsPatientResponsible = false;
            $scope.IsInsuranceAvailable = false;

            $scope.IsPatientResponsible = ($scope.mainClaimObject.BillPaymentTypeId == 1);
            $scope.IsInsuranceAvailable = Array.isArray($scope.AppointmentInsuranceList) && $scope.AppointmentInsuranceList.length > 0;
            var tempclaimScreenParentObj = {
                "PatientId": PatientId || null,
                "AppointmentId": AppointmentId || null,
                "VisitId": $scope.cacheStorageItem.VisitId || null,
                "ActionType": "AddClaim",
                "SubActionType": "Verify",
                "ScreenType": "Popup",
                "SuperBillId": null,
                "PatientClaimId": $scope.claimScreenParentObj.PatientClaimId,
                "SuperBillArray": [],
                "NotesId": NotesId || 1,
                "CardTypesData": $scope.CardTypesData || [],
                "AppointmentTypeId": $scope.claimScreenParentObj.AppointmentTypeId || 4,
            };

            datapersistanceFactory.set("IsComingFromClaim", tempclaimScreenParentObj);


            $scope.mInstanceAdd = $uibModal.open({
                "templateUrl": "templates/UsClaims/ClaimPatientProfile.html",
                //"size": "lg",
                "keyboard": false,
                "controller": "UsClaimPatientProfileCtrl",
                "windowClass": "modal__popup--1 bottom-to-top-modal  ",
                'backdrop': 'static',
                "resolve": {
                    "PatientInsuranceListData": function () { return item; },
                    "id": function () { return id; },
                    "AllHospitalData": function () { return $scope.mainBillerDataObj || null; },
                    "IshideIndicator": true,
                }

            });
            $scope.mInstanceAdd.result.then(function (PatientDetailsInd) {
                PatientDetailsInd = PatientDetailsInd || null;
                if (PatientDetailsInd === true) {
                    $scope.InsuredPatientDetails();
                    $scope.GetClaimDetails();
                } else {
                    $scope.InsuredPatientDetails();    // pavan1616 the indicator is getting null
                }
                $scope.getPatientDepositAmountById();

            }, function () { });

        }

