                $scope.mainClaimObject.TotalWriteOffAmount = $scope.ClaimDetails.TotalWriteOffAmount || 0;
                $scope.mainClaimObject.TotalInsuranceBalance = $scope.ClaimDetails.TotalInsuranceBalance || 0;
                $scope.mainClaimObject.TotalPatientBalance = $scope.ClaimDetails.TotalPatientBalance || 0;
                $scope.mainClaimObject.TotalBalance = $scope.ClaimDetails.TotalBalance || 0;
                $scope.mainClaimObject.ClaimFormId = $scope.ClaimDetails.ClaimFormId || null;
