        $scope.ClaimTransmissionHistory = function () {
            $scope.TransmissionHistoryList = [];
            let param = {
                "PatientClaimId": $scope.claimScreenParentObj.PatientClaimId || 0,
            }
            eHnoteInsuranceService.GetPatientClaimTransmitHistory(param).then(function (resp) {
                if (resp.data.status == "Success") {
                    $scope.TransmissionHistoryList = resp.data.rows || [];
                } else {
                    alertify.error(resp.data.Message);
                }
            });

        }


        function scrollToClaimLifeCycle(retryCount) {
            retryCount = retryCount || 0;

            var container = document.querySelector('.adjustable-position');
            var target = document.getElementById('table_claimlifecycle');

            if (container && target) {
                container.scrollTop = target.offsetTop - 20;
            }

            // 🔁 Retry until layout stabilizes
            if (retryCount < 5) {
                $timeout(function () {
                    scrollToClaimLifeCycle(retryCount + 1);
                }, 100);
            }
        }


        $scope.getClaimEventLogList = function () {
            $scope.claimEvenLogArray = [];
            var params = {
                "PatientClaimId": $scope.claimScreenParentObj.PatientClaimId,
                "PatientId": $scope.claimScreenParentObj.PatientId
            }

            const validStatusIds = [16, 17, 18, 19, 20, 21, 22, 23];

            eHnoteInsuranceService.GetPatientClaimEventLogDetails(params).then(function (resp) {
                console.log(JSON.stringify(resp));
                if (resp.data.status == "Success") {
                    if (resp.data.rows.length > 0) {
                        //$scope.claimEvenLogArray = resp.data.rows || [];
                        $scope.claimEvenLogArray = (resp.data.rows || []).map(item => {

                            item.showCheckNumberLink =
                                item.EraId &&
                                item.CheckNumber &&
                                validStatusIds.includes(item.EventClaimStatusId);

                            return item;
                        });
                    }

                    if ($scope.claimScreenParentObj.type == 'ClaimlifeCycle') {
                        // ✅ SCROLL AFTER DATA BINDS
                        //setTimeout(function () {
                        //    var container = document.querySelector('.adjustable-position');
                        //    var target = document.getElementById('table_claimlifecycle');

                        //    if (container && target) {
                        //        container.scrollTo({
                        //            top: target.offsetTop - 20,
                        //            behavior: 'smooth'
                        //        });
                        //    }
                        //}, 300);

                        $timeout(function () {
                            scrollToClaimLifeCycle();
                        }, 0);

                    }

                } else {
                    alertify.error(resp.data.Message);
                }
            }, function (err) {

            });
        }
        $scope.downloadEDIFile = function (textToSend) {
            eHnotePatientDataService.CreateEdiTextPdf(textToSend).then(function (response) {
                const fileUrl = response.data;
                fetch(fileUrl)
                    .then(res => res.blob())
                    .then(blob => {
                        const blobUrl = window.URL.createObjectURL(blob);
                        const a = document.createElement('a');
                        a.href = blobUrl;

                        const filename = ($scope.EdiItemData?.PatientFullName || 'Edi') + '_' +
                            ($scope.EdiItemData?.PatientClaimNumber || '837') + '.837'; // ⬅️ Use .837

                        a.download = filename;
                        document.body.appendChild(a);
                        a.click();
                        document.body.removeChild(a);
                        window.URL.revokeObjectURL(blobUrl);
                    })
                    .catch(err => {
                        alertify.error("Failed to download .837 file.");
                        console.error(err);
                    });

            }, function (error) {
                alertify.error("Failed to generate .837 file.");
                console.error(error);
            });
        };

        $scope.EDIFiledownload = function (formattedEdi) {

            if (!formattedEdi) {
                alertify.error("No EDI data available");
                return;
            }

            // 🔥 Convert formatted EDI back to RAW
            const rawEdi = formattedEdi.replace(/\n/g, '');

            eHnotePatientDataService.CreateEdiFileDownloadTextPdf(rawEdi)
                .then(function (response) {
                    const fileUrl = response.data;

                    fetch(fileUrl)
                        .then(res => res.blob())
                        .then(blob => {
                            const blobUrl = window.URL.createObjectURL(blob);
                            const a = document.createElement('a');
                            a.href = blobUrl;

                            const filename =
                                ($scope.EdiItemData?.PatientFullName || 'EDI') + '_' +
                                ($scope.EdiItemData?.PatientClaimNumber || '837') + '.837';

                            a.download = filename;

                            document.body.appendChild(a);
                            a.click();
                            document.body.removeChild(a);
                            window.URL.revokeObjectURL(blobUrl);
                        });
                })
                .catch(function (error) {
                    alertify.error("Failed to generate .837 file.");
                    console.error(error);
                });
        };




