        $scope.GetProcedurePayorPlanTypes = function (type) {
            type = type || "";
            $scope.PocedurePayorPlanTypes = [];
            let ClaimLineItems = [];
            $scope.mainClaimObject.RequirePreAuth = false;
            $scope.mainClaimObject.IsReferralRequired = false;

            if ($scope.mainClaimObject.PatientClaimLineItems.length == 0) {
                return false;
            } else {
                angular.forEach($scope.mainClaimObject.PatientClaimLineItems, function (item) {
                    item.ServiceId = item.ServiceId || 0;
                    if (item.ServiceId !== 0) {
                        let obj = {
                            "OrganizationProcedureId": item.OrganizationProcedureId,
                            "ProcedurePayorPlanId": item.ProcedurePayorPlanId,
                            "ServiceCode": item.ServiceCode,
                            "ServiceId": item.ServiceId,
                        }
                        ClaimLineItems.push(obj);
                    }
                });
            }

            let params = {
                "OrganizationId": $scope.HospitalId,
                "UserId": $scope.UserId,
                "RenderingProviderId": $scope.mainClaimObject.VisitProviderId || null,
                "OrganizationPayorId": $scope.PatientClaimTransmissionObj.OrganizationPayorId,
                "PlanId": $scope.PatientClaimTransmissionObj.PlanId,
                "ClaimLineItems": ClaimLineItems || []
            }
            eHnoteInsuranceService.GetProcedurePayorPlanTypes(params).then(function (resp) {
                console.log(resp);
                if (resp.data.status == "Success") {
                    $scope.PocedurePayorPlanTypes = resp.data.rows || [];

                    angular.forEach($scope.mainClaimObject.PatientClaimLineItems, function (item) {
                        let temparray = $filter("filter")($scope.PocedurePayorPlanTypes, { "OrganizationProcedureId": item.OrganizationProcedureId }, true) || [];
                        if (temparray.length > 0) {
                            if (temparray[0].RequirePreAuth === true) {
                                $scope.mainClaimObject.RequirePreAuth = true;
                            }
                            if (temparray[0].IsReferralRequired === true) {
                                $scope.mainClaimObject.IsReferralRequired = true;
                            }
                        }
                    });

                    if ($scope.mainClaimObject.PatientClaimId == 0) {
                        if ($scope.PocedurePayorPlanTypes.length > 0) {
                            angular.forEach($scope.mainClaimObject.PatientClaimLineItems, function (item) {
                                let temparray = $filter("filter")($scope.PocedurePayorPlanTypes, { "OrganizationProcedureId": item.OrganizationProcedureId }, true) || [];
                                if (temparray.length > 0) {
                                    if ($scope.mainClaimObject.BillPaymentTypeId == 1) {
                                        item.UnitCharge = temparray[0].ActualCost || 0;
                                    }
                                    else if ($scope.mainClaimObject.BillPaymentTypeId == 2 && $scope.mainClaimObject.ClaimTypeId === 2) {
                                        item.UnitCharge = temparray[0].InFacilityActualCost || 0;
                                    }
                                    else if ($scope.mainClaimObject.BillPaymentTypeId == 2 && $scope.mainClaimObject.ClaimTypeId === 1) {
                                        item.UnitCharge = temparray[0].OfficeActualCost || 0;
                                    } else {
                                        item.UnitCharge = temparray[0].ActualCost || 0;
                                    }

                                    if ($scope.isIojOrgEnable == true) {
                                        if (temparray[0].SpecialistValueType === "A") {
                                            item.DeductibleAmount = parseFloat(temparray[0].SpecialistCostvalue);
                                        } else {
                                            item.DeductibleAmount = (temparray[0].SpecialistCostvalue / 100) * item.UnitCharge;
                                        }
                                    }
                                    else {
                                        if (temparray[0].CoPayValueType === "A") {
                                            item.DeductibleAmount = parseFloat(temparray[0].CoPayCostValue);
                                        } else {
                                            item.DeductibleAmount = (temparray[0].CoPayCostValue / 100) * item.UnitCharge;
                                        }
                                    }

                                    item.TotalChargeAmount = item.UnitCharge * item.Quantity;
                                    item.PrimaryTotalChargeAmount = item.UnitCharge * item.Quantity;
                                    if ($scope.mainClaimObject.BillPaymentTypeId == 1) {
                                        item.PatientBalance = item.TotalChargeAmount;
                                        item.DeductibleAmount = item.PatientBalance;
                                    };
                                    if ($scope.mainClaimObject.BillPaymentTypeId == 2) {
                                        item.InsuranceBalance = item.TotalChargeAmount - item.DeductibleAmount;
                                        if ($scope.mainClaimObject.IsSecondaryInsuranceAvailable) {
                                            item.InsuranceBalance = item.TotalChargeAmount;
                                            /*item.DeductibleAmount = 0;*/
                                        } else {
                                            item.PatientBalance = item.DeductibleAmount;
                                            item.DeductibleAmount = item.PatientBalance;
                                        }
                                        if ($scope.AppointmentInsuranceList.length > 1) {
                                            item.PatientBalance = 0;
                                            /*  item.SecondaryUnitCharge = item.DeductibleAmount;*/

                                            item.SecondaryUnitCharge = parseFloat(item.DeductibleAmount).toFixed(2) || 0;
                                            item.SecondaryUnitCharge = Number(item.SecondaryUnitCharge);


                                            item.InsuranceBalance = item.TotalChargeAmount;
                                            item.DeductibleAmount = 0;
                                        }

                                    };

                                    temparray[0].ModifierId = temparray[0].ModifierId || 0;
                                    if (temparray[0].ModifierId != 0) {
                                        item.ModifierObj1 = $filter("filter")($scope.masterModifierList, { "MODIFIERID": temparray[0].ModifierId }, true)[0] || null;
                                    }

                                    if (temparray[0].RequirePreAuth === true) {
                                        $scope.mainClaimObject.RequirePreAuth = true;
                                    }
                                    if (temparray[0].IsReferralRequired === true) {
                                        $scope.mainClaimObject.IsReferralRequired = true;
                                    }
                                }
                            });
                            $scope.calculateLineItemsAmount();
                        }
                    }

                } else {
                    alertify.error(resp.data.Message);
                }
            }, function (err) {

            });
        }

