        $scope.calculateLineItemsPatientAmount = function (item) {
            item.UnitCharge = parseFloat(item.UnitCharge) || 0;
            item.PatientBalance = parseFloat(item.PatientBalance).toFixed(2) || 0;

            if (item.TotalChargeAmount < item.PatientBalance) {
                item.PatientBalance = 0;
                alertify.error("Charge amount is less than Patient Balance.");
                return false;
            }

            item.PatientResponsibilityAmount = parseFloat(item.PatientBalance) || 0; // typed = GROSS
            item.DeductibleAmount = item.PatientResponsibilityAmount;

            $scope.calculateLineItemsAmount();
        }


