        /*  drag and drop - start */

        $scope.draggedItemIndex = null;
        $scope.hoveredIndex = null;

        $scope.handleDragStart = function (index) {
            $scope.draggedItemIndex = index;
        };

        $scope.handleDrop = function (index) {
            if ($scope.draggedItemIndex === null || $scope.draggedItemIndex === index) return;

            const draggedItem = $scope.mainClaimObject.PatientClaimLineItems[$scope.draggedItemIndex];
            $scope.mainClaimObject.PatientClaimLineItems.splice($scope.draggedItemIndex, 1);
            $scope.mainClaimObject.PatientClaimLineItems.splice(index, 0, draggedItem);
            $scope.draggedItemIndex = null;
            $scope.$apply(); // manually trigger digest if needed
        };

        function GetDiagnosisPointer(billobj) {
            var diagnosisPointers = "";
            if (billobj.length > 0) {
                angular.forEach(billobj, function (item2) {
                    angular.forEach($scope.HCFADetailsInfo.DiagnosisList, function (ditem) {
                        if (item2.DiagnosisId === ditem.DiagnosisId) {
                            if (ditem.SNO === 1) {
                                diagnosisPointers = diagnosisPointers + "A";
                            }
                            if (ditem.SNO === 2) {
                                diagnosisPointers = diagnosisPointers + "B";
                            }
                            if (ditem.SNO === 3) {
                                diagnosisPointers = diagnosisPointers + "C";
                            }
                            if (ditem.SNO === 4) {
                                diagnosisPointers = diagnosisPointers + "D";
                            }
                            if (ditem.SNO === 5) {
                                diagnosisPointers = diagnosisPointers + "E";
                            }
                            if (ditem.SNO === 6) {
                                diagnosisPointers = diagnosisPointers + "F";
                            }
                            if (ditem.SNO === 7) {
                                diagnosisPointers = diagnosisPointers + "G";
                            }
                            if (ditem.SNO === 8) {
                                diagnosisPointers = diagnosisPointers + "H";
                            }
                            if (ditem.SNO === 9) {
                                diagnosisPointers = diagnosisPointers + "I";
                            }
                            if (ditem.SNO === 10) {
                                diagnosisPointers = diagnosisPointers + "J";
                            }
                            if (ditem.SNO === 11) {
                                diagnosisPointers = diagnosisPointers + "K";
                            }
                            if (ditem.SNO === 12) {
                                diagnosisPointers = diagnosisPointers + "L";
                            }
                        }
                    });
                });
            }
            return diagnosisPointers;
        }

