        $scope.changePrimaryBillerandMapProvider = function (BillingProviderGroupId, type) {

            console.log("checkPrimaryBillarandPrimaryProvider called" + BillingProviderGroupId);
            var primaryProviderId = $scope.mainClaimObject.BillingProviderId || 0;
            var PrimaryClaimTypeId = $scope.mainClaimObject.ClaimTypeId || 0;
            var RenderindProviderId = $scope.mainClaimObject.RenderingProviderId || 0;
            var RenderingProviderName = $scope.mainClaimObject.RenderingProviderName || "";
            $scope.PrimaryBillerName = $scope.mainClaimObject.RenderingProviderName || "";
            $scope.mainClaimObject.PrimaryProviderId = BillingProviderGroupId;
            if ($scope.OrganizationBillingProviderGroupsDetails.length > 0) {

                var OrgBillGroup = $filter("filter")($scope.OrganizationBillingProviderGroupsDetails, { BillingProviderGroupId: BillingProviderGroupId }, true) || [];
                $scope.mainClaimObject.EntityTypeId = 0;
                if (OrgBillGroup.length > 0) {
                    RenderindProviderId = OrgBillGroup[0].DoctorId;
                    primaryProviderId = OrgBillGroup[0].ParentOrgBillingProviderId;
                    $scope.mainClaimObject.EntityTypeId = OrgBillGroup[0].EntityTypeId;

                    console.log($scope.mainClaimObject.InsuranceCoverageTypeId + "__IsMedicare");
                    var covergaeInsuranceId = parseInt($scope.mainClaimObject.InsuranceCoverageTypeId) || 0;
                    if (covergaeInsuranceId === 2) {
                        console.log($scope.mainClaimObject.InsuranceCoverageTypeId + "__IsMedicare");
                        PrimaryClaimTypeId = OrgBillGroup[0].InsuranceFormTypeId;
                    }

                    RenderingProviderName = OrgBillGroup[0].DoctorFullName;
                    $scope.PrimaryBillerName = OrgBillGroup[0].Title + " " + RenderingProviderName;
                }


                var DoctorFilterArray = $filter("filter")($scope.filteredBranchDoctorsList, function (item, index) { return item.DoctorID == RenderindProviderId }, true);
                console.log(DoctorFilterArray);

                if (DoctorFilterArray.length > 0) {
                    $scope.DoctorObj = DoctorFilterArray[0];
                } else {
                    $scope.DoctorObj = "";
                    RenderindProviderId = 0;
                    RenderingProviderName = "";
                }


                $scope.mainClaimObject.RenderingProviderId = RenderindProviderId;
                $scope.mainClaimObject.RenderingProviderName = RenderingProviderName;
                $scope.mainClaimObject.BillingProviderId = primaryProviderId;
                if ($scope.mainClaimObject.PatientClaimId == 0) {
                    $scope.mainClaimObject.ClaimTypeId = PrimaryClaimTypeId;
                    $scope.mainClaimObject.ClaimFormId = PrimaryClaimTypeId;
                }


                //if ($scope.mainClaimObject.OrganizationId === 4) {
                //    $scope.mainClaimObject.PlaceOfServiceId = 24;
                //    $scope.mainClaimObject.PlaceOfServiceName = "ASC";
                //} else {
                //    $scope.mainClaimObject.PlaceOfServiceId = 11;
                //    $scope.mainClaimObject.PlaceOfServiceName = "Office";
                //}

                type = type || "";
                var ServiceLocationObj = $filter("filter")($scope.AllUserBranchesList, { 'ClinicId': $scope.mainClaimObject.OrganizationId }) || [];
                if (ServiceLocationObj.length > 0 && type !== "Edit") {
                    $scope.mainClaimObject.PlaceOfServiceId = ServiceLocationObj[0].PlaceOfServiceId || 11;
                    //$scope.mainClaimObject.PlaceOfServiceName = ServiceLocationObj[0].PlaceOfServiceName || 'Office';
                    var POSfiltredArray = $filter("filter")($scope.masterPlaceOfServiceArray, { "PlaceOfServiceId": $scope.mainClaimObject.PlaceOfServiceId }, true) || [];
                    if (POSfiltredArray.length > 0) {
                        $scope.mainClaimObject.PlaceOfServiceName = POSfiltredArray[0].PlaceofServiceCode + '-' + POSfiltredArray[0].PlaceofServiceName;
                    }
                }



                //if ($scope.mainClaimObject.ClaimTypeId === 1) {
                //    $scope.mainClaimObject.PlaceOfServiceId = 11;
                //    $scope.mainClaimObject.PlaceOfServiceName = "Office";
                //} else if ($scope.mainClaimObject.ClaimTypeId === 2) {
                //    $scope.mainClaimObject.PlaceOfServiceId = 24;
                //    $scope.mainClaimObject.PlaceOfServiceName = "ASC";
                //}
            }

            if ($scope.UserId == 1604 ||$scope.UserId == 386 ||($scope.isIojOrgEnable && $scope.UserId == 2)) {
                $scope.GetFeeScheduleByProcedureTypes();
            } else {
                $scope.GetProcedurePayorPlanTypes();
            }

        }


