                            "ToDate": $filter('date')(pitem.DOSto, 'MM-dd-yyyy') || "",
                            "PlaceOfService": $scope.HCFADetailsInfo.PlaceOfServiceName || "",
                            "PlaceOfServiceId": $scope.HCFADetailsInfo.PlaceOfServiceId || "",
