                                $scope.UBDetailsInfo.PatientsReasonforVisitObj.Reason1 = ditem.ICDCode || "";
                                $scope.UBDetailsInfo.ExternalCauseofInjuryObj[0].Code = ditem.ICDCode || "";
                                $scope.UBDetailsInfo.ExternalCauseofInjuryObj[0].PresentonAdmission = "Y";
