        $scope.syncDxPointers = function (item) {

            //if (item.DiagnosisId == 0) return;

            let filteredDiagnosisList = angular.copy($scope.DiagnosisListArray) || [];
            let sortedList = filteredDiagnosisList.sort((a, b) => a.Type.localeCompare(b.Type));

            let deleteIndex = sortedList.findIndex(x => x.Type === item.Type);
            if (deleteIndex === -1) return;

            for (let i = deleteIndex; i < sortedList.length - 1; i++) {

                sortedList[i].DiagnosisId = sortedList[i + 1].DiagnosisId;
                sortedList[i].DiagnosisName = sortedList[i + 1].DiagnosisName;
                sortedList[i].ICDCode = sortedList[i + 1].ICDCode;

                const code = sortedList[i + 1].ICDCode || "";
                const name = sortedList[i + 1].DiagnosisName || "";

                sortedList[i].SelectedObj = (code || name) ? `${code} - ${name}` : "";
                sortedList[i].SuperBillDiagnosisId = sortedList[i + 1].SuperBillDiagnosisId;
                sortedList[i].DiagnosisTypeId = sortedList[i + 1].DiagnosisTypeId;
                sortedList[i].SelectedCode = sortedList[i + 1].SelectedCode;

            }

            let last = sortedList.length - 1;
            sortedList[last].DiagnosisId = 0;
            sortedList[last].DiagnosisName = "";
            sortedList[last].ICDCode = "";
            sortedList[last].SelectedObj = "";
            sortedList[last].SuperBillDiagnosisId = null;
            sortedList[last].DiagnosisTypeId = null;
            sortedList[last].SelectedCode = "";

            if ($scope.mainClaimObject.ActionType === 'SuperBill') {
                const id = item.SuperBillDiagnosisId || 0;

                if (id) {
                    const f = $filter("filter")($scope.cacheStorageItem.SuperBillDiagnosisArray, { "SuperBillDiagnosisId": id }, true) || [];
                    if (f.length) f[0].DeleteInd = "Y";
                } else {
                    const i = $scope.cacheStorageItem.SuperBillDiagnosisArray.indexOf(item);
                    if (i > -1) $scope.cacheStorageItem.SuperBillDiagnosisArray.splice(i, 1);
                }

                console.log("__Super Bill Diagnosis", $scope.cacheStorageItem.SuperBillDiagnosisArray);
            }


            let validDiagnosisList = sortedList.filter(x => x.DiagnosisId != 0);
            let validIds = validDiagnosisList.map(x => x.DiagnosisId);

            let filteredPatientClaimList = angular.copy($scope.mainClaimObject.PatientClaimLineItems) || [];

            angular.forEach(filteredPatientClaimList, function (lineItem) {

                lineItem.DiagnosisList.forEach(d => {
                    if (!validIds.includes(d.DiagnosisId)) {
                        d.DeleteInd = 'Y';
                    }
                });

                let activeList = lineItem.DiagnosisList.filter(d => d.DeleteInd !== 'Y');

                if (activeList.length > 0) {

                    activeList.sort((a, b) => a.Type.localeCompare(b.Type));
                    activeList.forEach(d => {
                        if (d.Type && d.Type >= item.Type && d.Type <= 'Z') {
                            d.Type = String.fromCharCode(d.Type.charCodeAt(0) - 1);
                        }
                    });


                    lineItem.DiagnosisList.forEach(d => {

                        d.SuperbillItemDiagnosisId = d.SuperbillItemDiagnosisId || 0;
                        d.PatientClaimLineItemDiagnosisId = d.PatientClaimLineItemDiagnosisId || 0;

                        if (d.DeleteInd == 'N' && (d.SuperbillItemDiagnosisId != 0 || d.PatientClaimLineItemDiagnosisId != 0)) {

                            const updated = activeList.find(x => x.DiagnosisId === d.DiagnosisId);

                            d.DiagnosisId = updated.DiagnosisId;
                            d.DiagnosisName = updated.DiagnosisName;
                            d.ICDCode = updated.ICDCode;
                            d.Type = updated.Type;
                            d.DeleteInd = updated.DeleteInd;
                            d.PatientClaimLineItemDiagnosisId = updated.PatientClaimLineItemDiagnosisId;
                            d.SuperbillItemDiagnosisId = updated.SuperbillItemDiagnosisId;
                            d.ClaimLineItemId = updated.ClaimLineItemId;
                            d.PatientClaimId = updated.PatientClaimId;

                        } else {
                            if (d.DeleteInd === 'Y' && (($scope.mainClaimObject.ActionType === 'SuperBill' && d.SuperbillItemDiagnosisId === 0) || ($scope.mainClaimObject.ActionType === 'AddClaim' && d.PatientClaimLineItemDiagnosisId === 0))) {
                                const index = (lineItem.DiagnosisList || []).findIndex(x => x.DiagnosisId === d.DiagnosisId);
                                if (index > -1) lineItem.DiagnosisList.splice(index, 1);
                            }
                        }
                    });


                    lineItem.DiagnosisIds = [];
                    lineItem.DiagnosisList.forEach(d => {
                        var obj = {
                            "DiagnosisId": d.DiagnosisId,
                            "ICDCode": d.ICDCode,
                            "Type": d.Type,
                            "DeleteInd": d.DeleteInd
                        }
                        lineItem.DiagnosisIds.push(obj);
                    });

                }

                var Index = (lineItem.addedDiagnosisArray || []).findIndex(x => x.DiagnosisId === item.DiagnosisId);
                if (Index > -1) lineItem.addedDiagnosisArray.splice(Index, 1);

                lineItem.addedDiagnosisArray.sort((a, b) => a.Type.localeCompare(b.Type));
                lineItem.addedDiagnosisArray.forEach(d => {
                    if (d.Type && d.Type >= item.Type && d.Type <= 'Z') {
                        d.Type = String.fromCharCode(d.Type.charCodeAt(0) - 1);
                    }
                });

                var checkedArray = (lineItem.addedDiagnosisArray || []).filter(d => d.IsSelected).sort((a, b) => a.SelectedOrder - b.SelectedOrder);

                lineItem.DiagnosisPointers = checkedArray.map(d => d.Type).join(",");

            });

            $scope.mainClaimObject.PatientClaimLineItems = angular.copy(filteredPatientClaimList) || [];

            $scope.DiagnosisListArray = angular.copy(sortedList) || [];

            console.log("__Delete Patient Claim Line Items", $scope.mainClaimObject.PatientClaimLineItems);
            console.log("__Delete Diagnosis List", $scope.DiagnosisListArray);
        };



        $scope.GetPatientNotesAlertsById = function () {

            $scope.PatientAlertsList = [];
            let obj = {
                "PatientId": $scope.PatientId,
                "OrganizationId": $scope.HospitalId,
                "StatusId": 1
            }
            eHnoteInsuranceService.GetPatientAlertsNew(obj).then(function (resp) {
                if (resp.data.Status == "Success") {
                    if (resp.data.rows.length > 0) {
                        $scope.PatientAlertsList = resp.data.rows || [];

                        $scope.PatientAlerts = [];

                        if ($scope.PatientAlertsList.length > 0) {
                            angular.forEach($scope.PatientAlertsList, function (item) {
                                var counter = 0;
                                if (item.AlertData !== null) {
                                    if (item.AlertData.AlertTypesList.length > 0) {
                                        angular.forEach(item.AlertData.AlertTypesList, function (Bitem) {
                                            if (Bitem.AlertTypeId == 4) {
                                                counter++;
                                            }
                                        })
                                    }
                                }
                                if (counter !== 0) {
                                    $scope.PatientAlerts.push(item);
                                }
                            });
                        }

                    }
                } else {
                    alertify.error(resp.data.Message);
                }
            });
        }
      

        $scope.GetPatientNotesAlertsById();

        $scope.GetFeeScheduleByProcedureTypes = function () {

            $scope.PocedurePayorPlanTypes = [];
            let ClaimLineItems = [];

            if ($scope.mainClaimObject.PatientClaimLineItems.length == 0) {
                return false;
            } else {
                angular.forEach($scope.mainClaimObject.PatientClaimLineItems, function (item) {

                    item.ServiceId = item.ServiceId || 0;
                    if (item.ServiceId != 0) {
                        let obj = {
                            "OrganizationProcedureId": item.OrganizationProcedureId,
                            "ServiceCode": item.ServiceCode,
                            "ServiceId": item.ServiceId,
                            "DOSDate": item.DOSfrom || null,
                        }
                        ClaimLineItems.push(obj);
                    }
                });
            }

            var OrganizationPayorId = null;
            var PayerId = null;
            var PlanId = null;

            if ($scope.ClaimTransInsuranceList.length > 0) {
                OrganizationPayorId = $scope.ClaimTransInsuranceList[0].OrganizationPayorId;
                PayerId = $scope.ClaimTransInsuranceList[0].PayorId;
                PlanId = $scope.ClaimTransInsuranceList[0].PlanId;
            }

            if ($scope.mainClaimObject.BillPaymentTypeId == 1) {
                OrganizationPayorId = null;
                PayerId = null;
                PlanId = null;
            }

            if (!$scope.mainClaimObject.AdmissionDate) {
                $scope.mainClaimObject.AdmissionDate = $scope.claimScreenParentObj.AppointmentDate;
            }

            let params = {
                //"ParentOrganizationId": $scope.ParenthospitalId,
               // "OrganizationPayorId": $scope.PatientClaimTransmissionObj.OrganizationPayorId,
               // "PlanId": $scope.PatientClaimTransmissionObj.PlanId,
                "OrganizationId": $scope.mainClaimObject.OrganizationId || $scope.HospitalId,
                "UserId": $scope.UserId,
                "OrganizationPayorId": OrganizationPayorId,
                "PlanId": PlanId,
                "BillPaymentTypeId": $scope.mainClaimObject.BillPaymentTypeId || null,
                "BillingProviderId": $scope.mainClaimObject.BillingProviderId || null,
                "DOSDate": $scope.mainClaimObject.AdmissionDate || null,
                "ClaimLineItems": ClaimLineItems || []
            }
            eHnoteInsuranceService.GetProcedurePayorFeeScheduleDetails(params).then(function (resp) {
                console.log(resp);
                if (resp.data.status === "Success") {

                    const procedureFeeList = resp.data.rows || [];
                    const lineItems = $scope.mainClaimObject.PatientClaimLineItems || [];

                    // -------------------------------
                    // PreAuth & Referral flags
                    // -------------------------------
                    lineItems.forEach(item => {
                        const fee = procedureFeeList.find(x => x.OrganizationProcedureId === item.OrganizationProcedureId);

                        if (fee) {
                            if (fee.RequirePreAuth) {
                                $scope.mainClaimObject.RequirePreAuth = true;
                            }
                            if (fee.IsReferralRequired) {
                                $scope.mainClaimObject.IsReferralRequired = true;
                            }
                        }
                    });

                    // -------------------------------
                    // Only for new claims
                    // -------------------------------
                    if ($scope.mainClaimObject.PatientClaimId !== 0 || !procedureFeeList.length) {
                        return;
                    }

                    //const today = new Date();
                    //today.setHours(0, 0, 0, 0);
                    
                    const today = moment($scope.mainClaimObject.AdmissionDate).startOf('day');

                    const hasInsurance = Array.isArray($scope.AppointmentInsuranceList) && $scope.AppointmentInsuranceList.length > 0;

                    const payorId = hasInsurance ? $scope.PatientClaimTransmissionObj.OrganizationPayorId : null;

                    const isASCVisit = [4, 6, 7, 14].includes($scope.mainClaimObject.AppointmentTypeId);
                    const feeKey = isASCVisit ? "FinalMedicareASCFee" : "FinalMedicareOfficeFee";

                    // -------------------------------
                    // Filter valid fee rows
                    // -------------------------------
                    const validFees = procedureFeeList.filter(r => {
                        if (!r.EffectiveFrom || !r.EffectiveTo) return false;

                        //const from = new Date(r.EffectiveFrom);
                        //const to = new Date(r.EffectiveTo);
                        //from.setHours(0, 0, 0, 0);
                        //to.setHours(23, 59, 59, 999);

                        const from = moment(r.EffectiveFrom, "YYYY-MM-DD").startOf('day').toDate();
                        const to = moment(r.EffectiveTo, "YYYY-MM-DD").endOf('day').toDate();

                        return (
                            r.ParentOrganizationId === $scope.ParenthospitalId &&
                            r.OrganizationId === $scope.mainClaimObject.OrganizationId &&
                            /* r.BillingProviderId === $scope.mainClaimObject.BillingProviderId &&*/
                            //(!payorId || r.OrganizationPayorId === payorId) &&
                            today >= from &&
                            today <= to &&
                            r.ActiveInd === "Y" &&
                            r.IsActive === true
                        );
                    });

                    // -------------------------------
                    // Apply charges & modifiers
                    // -------------------------------
                    //lineItems.forEach(item => {
                    //    const fee = validFees.find(x => x.OrganizationProcedureId === item.OrganizationProcedureId);

                    //    if (fee) {
                    //        item.UnitCharge = fee[feeKey];
                    //        const found = $filter('filter')($scope.masterModifierList, { "ModifierCode": fee.ModifierCode }, true) || [];
                    //        if (found.length) {
                    //            item.ModifierObj1 = found[0];
                    //            item.Modifier1 = found[0].ModifierCode;
                    //        }
                    //    }
                    //});

                    if (validFees.length) {
                        if ($scope.mainClaimObject.BillPaymentTypeId == 2 && $scope.mainClaimObject.ClaimTypeId === 2) {

                            angular.forEach($scope.mainClaimObject.PatientClaimLineItems, function (item) {

                                let temparray = $filter("filter")(validFees, { "OrganizationProcedureId": item.OrganizationProcedureId }, true) || [];

                                if (temparray.length > 0) {

                                    item.UnitCharge = temparray[0].MedicareASCFee;
                                    item.IsRequirePreAuth = temparray[0].RequirePreAuth;
                                    item.IsProcedureNotCoveredByInsurance = temparray[0].ProcedureNotCoveredByInsurance;
                                    item.IsReferralRequired = temparray[0].IsReferralRequired;
                                    item.ModifierObj1 = temparray[0].ModifierCode;

                                    if ($scope.isIojOrgEnable == true) {
                                        if (temparray[0].SpecialistValueType === "A") {
                                            item.DeductibleAmount = parseFloat(temparray[0].SpecialistCostvalue);
                                        } else {
                                            item.DeductibleAmount = (temparray[0].SpecialistCostvalue / 100) * item.UnitCharge;
                                        }
                                    }
                                    else {
                                        if (temparray[0].CoPayValueType === "A") {
                                            item.DeductibleAmount = parseFloat(temparray[0].CoPayCostValue);
                                        } else {
                                            item.DeductibleAmount = (temparray[0].CoPayCostValue / 100) * item.UnitCharge;
                                        }
                                    }

                                    item.TotalChargeAmount = item.UnitCharge * item.Quantity;
                                    item.PrimaryTotalChargeAmount = item.UnitCharge * item.Quantity;

                                    item.InsuranceBalance = item.TotalChargeAmount - item.DeductibleAmount;
                                    if ($scope.mainClaimObject.IsSecondaryInsuranceAvailable) {
                                        item.InsuranceBalance = item.TotalChargeAmount;
                                        /*item.DeductibleAmount = 0;*/
                                    } else {
                                        item.PatientBalance = item.DeductibleAmount;
                                        item.DeductibleAmount = item.PatientBalance;
                                    }
                                    if ($scope.AppointmentInsuranceList.length > 1) {
                                        item.PatientBalance = 0;
                                        /*  item.SecondaryUnitCharge = item.DeductibleAmount;*/

                                        item.SecondaryUnitCharge = parseFloat(item.DeductibleAmount).toFixed(2) || 0;
                                        item.SecondaryUnitCharge = Number(item.SecondaryUnitCharge);


                                        item.InsuranceBalance = item.TotalChargeAmount;
                                        item.DeductibleAmount = 0;
                                    }
                                }
                            });

                        } else {

                            angular.forEach($scope.mainClaimObject.PatientClaimLineItems, function (item) {

                                let temparray = $filter("filter")(validFees, { "OrganizationProcedureId": item.OrganizationProcedureId }, true) || [];

                                if (temparray.length > 0) {

                                    item.UnitCharge = temparray[0].MedicareOfficeFee;
                                    item.IsRequirePreAuth = temparray[0].RequirePreAuth;
                                    item.IsProcedureNotCoveredByInsurance = temparray[0].ProcedureNotCoveredByInsurance;
                                    item.IsReferralRequired = temparray[0].IsReferralRequired;
                                    item.ModifierObj1 = temparray[0].ModifierCode;

                                    if ($scope.isIojOrgEnable == true) {
                                        if (temparray[0].SpecialistValueType === "A") {
                                            item.DeductibleAmount = parseFloat(temparray[0].SpecialistCostvalue);
                                        } else {
                                            item.DeductibleAmount = (temparray[0].SpecialistCostvalue / 100) * item.UnitCharge;
                                        }
                                    }
                                    else {
                                        if (temparray[0].CoPayValueType === "A") {
                                            item.DeductibleAmount = parseFloat(temparray[0].CoPayCostValue);
                                        } else {
                                            item.DeductibleAmount = (temparray[0].CoPayCostValue / 100) * item.UnitCharge;
                                        }
                                    }

                                    item.TotalChargeAmount = item.UnitCharge * item.Quantity;
                                    item.PrimaryTotalChargeAmount = item.UnitCharge * item.Quantity;

                                    item.InsuranceBalance = item.TotalChargeAmount - item.DeductibleAmount;
                                    if ($scope.mainClaimObject.IsSecondaryInsuranceAvailable) {
                                        item.InsuranceBalance = item.TotalChargeAmount;
                                        /*item.DeductibleAmount = 0;*/
                                    } else {
                                        item.PatientBalance = item.DeductibleAmount;
                                        item.DeductibleAmount = item.PatientBalance;
                                    }
                                    if ($scope.AppointmentInsuranceList.length > 1) {
                                        item.PatientBalance = 0;
                                        /*  item.SecondaryUnitCharge = item.DeductibleAmount;*/

                                        item.SecondaryUnitCharge = parseFloat(item.DeductibleAmount).toFixed(2) || 0;
                                        item.SecondaryUnitCharge = Number(item.SecondaryUnitCharge);


                                        item.InsuranceBalance = item.TotalChargeAmount;
                                        item.DeductibleAmount = 0;
                                    }
                                }
                            });
                        }

                        if ($scope.mainClaimObject.BillPaymentTypeId == 1) {
                            if (isASCVisit) {
                                angular.forEach($scope.mainClaimObject.PatientClaimLineItems, function (item) {

                                    let temparray = $filter("filter")(validFees, { "OrganizationProcedureId": item.OrganizationProcedureId }, true) || [];

                                    if (temparray.length > 0) {

                                        item.UnitCharge = temparray[0].MedicareASCFee;
                                        item.IsRequirePreAuth = temparray[0].RequirePreAuth;
                                        item.IsProcedureNotCoveredByInsurance = temparray[0].ProcedureNotCoveredByInsurance;
                                        item.IsReferralRequired = temparray[0].IsReferralRequired;
                                        item.ModifierObj1 = temparray[0].ModifierCode;

                                        if ($scope.isIojOrgEnable == true) {
                                            if (temparray[0].SpecialistValueType === "A") {
                                                item.DeductibleAmount = parseFloat(temparray[0].SpecialistCostvalue);
                                            } else {
                                                item.DeductibleAmount = (temparray[0].SpecialistCostvalue / 100) * item.UnitCharge;
                                            }
                                        }
                                        else {
                                            if (temparray[0].CoPayValueType === "A") {
                                                item.DeductibleAmount = parseFloat(temparray[0].CoPayCostValue);
                                            } else {
                                                item.DeductibleAmount = (temparray[0].CoPayCostValue / 100) * item.UnitCharge;
                                            }
                                        }

                                        item.PatientBalance = item.TotalChargeAmount;
                                        item.DeductibleAmount = item.PatientBalance;
                                    }
                                });
                            } else {
                                angular.forEach($scope.mainClaimObject.PatientClaimLineItems, function (item) {

                                    let temparray = $filter("filter")(validFees, { "OrganizationProcedureId": item.OrganizationProcedureId }, true) || [];

                                    if (temparray.length > 0) {

                                        item.UnitCharge = temparray[0].MedicareOfficeFee;
                                        item.IsRequirePreAuth = temparray[0].RequirePreAuth;
                                        item.IsProcedureNotCoveredByInsurance = temparray[0].ProcedureNotCoveredByInsurance;
                                        item.IsReferralRequired = temparray[0].IsReferralRequired;
                                        item.ModifierObj1 = temparray[0].ModifierCode;

                                        if ($scope.isIojOrgEnable == true) {
                                            if (temparray[0].SpecialistValueType === "A") {
                                                item.DeductibleAmount = parseFloat(temparray[0].SpecialistCostvalue);
                                            } else {
                                                item.DeductibleAmount = (temparray[0].SpecialistCostvalue / 100) * item.UnitCharge;
                                            }
                                        }
                                        else {
                                            if (temparray[0].CoPayValueType === "A") {
                                                item.DeductibleAmount = parseFloat(temparray[0].CoPayCostValue);
                                            } else {
                                                item.DeductibleAmount = (temparray[0].CoPayCostValue / 100) * item.UnitCharge;
                                            }
                                        }
                                    }
                                });
                            }
                        }
                    }

                    $scope.calculateLineItemsAmount();
                }
                else {
                    alertify.error(resp.data.Message);
                }
            }, function (err) {

            });
        }

