                        $scope.EOBPrintMainObj.ClaimPaymentInfo = MatchedClaimsList || [];
                        $scope.EOBPrintMainObj.ClaimAdjustments = [];
                        $scope.EOBPrintMainObj.ClaimLegends = [];
                        $scope.EOBPrintMainObj.PrintedDatenTime = "";


