        $scope.Opento277AcknowledgementPrint = function (item) {

            var printDate = $filter("date")(new Date(), "MMM-dd-yyyy");
            var printTime = moment(new Date()).format("HH:mm");
            $scope.AckPrintedDatenTime = printDate + ',  ' + printTime;

            $scope.AckPrintDetails = {
                "CreatedDt": item.CreatedDt,
                "CreatedTime": item.CreatedTime,
                "FileName": item.FileName,
                "BillingProvider": $scope.ClaimDetails.RenderingProviderFirstName + ' ' + $scope.ClaimDetails.RenderingProviderLastName + '-' + $scope.ClaimDetails.RenderingProviderNPI,
                "PayerName": $scope.AppointmentInsuranceList[0].PayorName,
                "CreatedByUserName": item.CreatedByUserName,
                "Action": item.Notes,
                "rows": []
            };

            let obj = {
                'PatientClaimId': item.PatientClaimId || '',
                'TransactionId': item.TransactionId || '',
            }

            eHnoteInsuranceService.Get277AcknowledgementsRespons(obj).then(function (resp) {

                console.log(resp);
                if (resp.data.Status == 'Success') {
                    $scope.AckPrintDetails.rows = resp.data.rows || [];
                    $scope.AckPrintDetails.ClearingHouseName = resp.data.rows[0].ClearingHouseName || "";

                    if ($scope.AckPrintDetails.rows.length > 0) {
                        angular.forEach($scope.AckPrintDetails.rows, function (item) {
                            item.ICNNum = "";
                            if (item.PayerClaimNumber != null) {
                                item.ICNNum = "/" + item.PayerClaimNumber;
                            }

                        })
                    }
                }

                $timeout(function () {
                    var innerContents = document.getElementById('277Acknowledgement_print').innerHTML;
                    var popupWinindow = window.open('scrollbars=no,menubar=no,toolbar=no,location=no,status=no,titlebar=no');
                    popupWinindow.document.open();
                    popupWinindow.document.write('<html><head><link rel="stylesheet" type="text/css" href="css/billing.css" /></head><body onload="window.print()" class="bodyheightprint">' + innerContents + '</body></html>');
                    popupWinindow.document.close();
                }, 1000);
            }, function () {
                alertify.error("Error loading report");
            });
        }


        $scope.unitcostpopup = function (lineitem, mainobj) {
            console.log(lineitem);
            console.log(mainobj);


            var obj = {
                "lineitem": lineitem,
                "mainBillingObj": mainobj,
                "UserId": $scope.UserId,
                "HospitalId": $scope.HospitalId
            }

            $scope.mCostInstanceAdd = $uibModal.open({
                "templateUrl": "unitcostpopup.html",
                /*"size": "lg",*/
                "backdrop": "static",
                "keyboard": false,
                "scope": $scope,
                "resolve": {
                    "mainObject": function () { return obj; },
                },
                "windowClass": "modal__sixty--",
                "controller": function ($scope, $uibModal, $uibModalInstance, mainObject) {

                    console.log(mainObject);

                    $scope.outSIdeMainbillingObj = mainObject.mainBillingObj;
                    $scope.outSideMaiLineItem = mainObject.lineitem;

                   

                    var isSecondaryInsAvail = false;
                    $scope.selectedLineItemObj = {
                        "UserId": $scope.UserId,
                        "ClaimLineItemId": $scope.outSideMaiLineItem.ClaimLineItemId,
                        "ProcedureId": $scope.outSideMaiLineItem.ServiceId,
                        "ProcedureName": $scope.outSideMaiLineItem.ServiceName,
                        "CPTCode": $scope.outSideMaiLineItem.ServiceCode,
                        "TotalChargeAmount": $scope.outSideMaiLineItem.TotalChargeAmount || 0,
                        "TotalAdjustmentAmount": $scope.outSideMaiLineItem.AdjustmentAmount || 0,
                        "TotalWriteOffAmount": $scope.outSideMaiLineItem.WriteOffAmount || 0,
                        "TotalInsurancePaymentAmount": $scope.outSideMaiLineItem.InsurancePaymentAmount || 0,
                        "TotalPatientPaymentAmount": $scope.outSideMaiLineItem.PatientPaymentAmount || 0,
                        "TotalPatientBalance": $scope.outSideMaiLineItem.PatientBalance || 0,
                        "TotalInsuranceBalance": $scope.outSideMaiLineItem.InsuranceBalance || 0,
                        "TotalBalance": $scope.outSideMaiLineItem.TotalBalance || 0,
                        "CostDetails": []
                    };

                    function getNewInsuranceWiseCostObj() {
                        var obj = {
                            "ClaimLineItemId": 0,
                            "PatientInsuranceDetailId": 0,
                            "IdentifierId": 1,
                            "OrganizationPayorId": 0,
                            "MasterPayorId": 0,
                            "PayorName": "",
                            "PayorCode": "",
                            "ProcedureId": 0,
                            "ProcedureName": "",
                            "CPTCode": "",
                            "Modifier1": "",
                            "Modifier2": "",
                            "ModifierCode1": "",
                            "ModifierCode2": "",
                            "ChargeAmount": 0,
                            "DeductibleAmount": 0,
                            "ExpectedAmount": 0
                        };
                        return obj;
                    }




                    if ($scope.outSIdeMainbillingObj.AppointmentInsuranceDetails.length > 0) {

                        angular.forEach($scope.outSIdeMainbillingObj.AppointmentInsuranceDetails, function (pitem) {

                            $scope.InsuranceWiseCostObj = getNewInsuranceWiseCostObj();
                            $scope.InsuranceWiseCostObj.ClaimLineItemId = $scope.outSideMaiLineItem.ClaimLineItemId;
                            $scope.InsuranceWiseCostObj.PatientInsuranceDetailId = pitem.PatientInsuranceDetailId;
                            $scope.InsuranceWiseCostObj.IdentifierId = pitem.IdentifierId;
                            $scope.InsuranceWiseCostObj.OrganizationPayorId = pitem.OrganizationPayorId;
                            $scope.InsuranceWiseCostObj.MasterPayorId = pitem.PayorId;
                            $scope.InsuranceWiseCostObj.PayorName = pitem.PayorName;
                            $scope.InsuranceWiseCostObj.PayorCode = pitem.PayorCode;
                            $scope.InsuranceWiseCostObj.ProcedureId = $scope.outSideMaiLineItem.ServiceId;
                            $scope.InsuranceWiseCostObj.ProcedureName = $scope.outSideMaiLineItem.ServiceName;
                            $scope.InsuranceWiseCostObj.CPTCode = $scope.outSideMaiLineItem.ServiceCode;
                            $scope.InsuranceWiseCostObj.Modifier1 = $scope.outSideMaiLineItem.Modifier1;
                            $scope.InsuranceWiseCostObj.Modifier2 = $scope.outSideMaiLineItem.Modifier2;
                            $scope.InsuranceWiseCostObj.ModifierCode1 = $scope.outSideMaiLineItem.ModifierCode1;
                            $scope.InsuranceWiseCostObj.ModifierCode2 = $scope.outSideMaiLineItem.ModifierCode2;
                            $scope.InsuranceWiseCostObj.ChargeAmount = $scope.outSideMaiLineItem.UnitCharge || 0;
                            if ($scope.outSideMaiLineItem.IsSecondaryChargeEdited) {
                                $scope.InsuranceWiseCostObj.ChargeAmount = $scope.outSideMaiLineItem.SecondaryUnitCharge;
                            }

                            $scope.outSideMaiLineItem.SecondaryUnitCharge = $scope.outSideMaiLineItem.SecondaryUnitCharge || 0;
                            if ($scope.outSideMaiLineItem.SecondaryUnitCharge != 0) {
                                $scope.InsuranceWiseCostObj.ChargeAmount = $scope.outSideMaiLineItem.SecondaryUnitCharge;
                            }

                            $scope.InsuranceWiseCostObj.DeductibleAmount = 0;
                            $scope.InsuranceWiseCostObj.ExpectedAmount = 0;
                            $scope.selectedLineItemObj.CostDetails.push($scope.InsuranceWiseCostObj);
                            if (pitem.IdentifierId === 2 && $scope.outSIdeMainbillingObj.AppointmentInsuranceDetails.length > 1) {
                                isSecondaryInsAvail = true;
                            }
                        });
                    }


                    $scope.uibclose = function () {
                        $uibModalInstance.dismiss("cancel");
                    };

                    $scope.navtosavethesecondarychargeandcontinue = function () {
                        $scope.isPrimarychargeEdited = false;
                        var primarychargeamount = 0;
                        var secondarychargeamount = 0;
                        $scope.isSecondarychargeEdited = false;


                        var filtredsecondaryCostLineitem = $filter('filter')($scope.selectedLineItemObj.CostDetails, { "IdentifierId": 2 }, true) || [];

                        if (filtredsecondaryCostLineitem.length > 0) {
                            secondarychargeamount = parseFloat(filtredsecondaryCostLineitem[0].ChargeAmount) || 0;
                        }

                        //if (secondarychargeamount === 0) {
                        //    alertify.error("please enter amount");
                        //    return false;
                        //}

                        if (isSecondaryInsAvail && secondarychargeamount > 0) {
                            if ($scope.selectedLineItemObj.TotalChargeAmount === secondarychargeamount) {

                            } else if ($scope.selectedLineItemObj.TotalChargeAmount !== secondarychargeamount) {
                                $scope.isSecondarychargeEdited = true;
                            }
                        }

                        if ($scope.isSecondarychargeEdited) {
                            $scope.continuetoSaveSecondaryCharge(secondarychargeamount);
                        }

                    }

                    $scope.continuetoSaveSecondaryCharge = function (secondarychargeamount) {

                        var respobj = {
                            "isPrimarychargeEdited": false,
                            "isSecondarychargeEdited": true,
                            "PrimaryChargeAmount": 0,
                            "SecondryChargeAmount": secondarychargeamount
                        }


                        $uibModalInstance.close(respobj);


                    }


                    $scope.GetOrganizationPayorCPTCost = function (type) {
                        type = type || "";
                        $scope.PocedurePayorPlanTypes = [];
                        let ClaimLineItems = [];

                        let obj = {
                            "OrganizationProcedureId": lineitem.OrganizationProcedureId,
                            "ProcedurePayorPlanId": lineitem.ProcedurePayorPlanId,
                            "ServiceCode": lineitem.ServiceCode,
                            "ServiceId": lineitem.ServiceId,
                        }
                        ClaimLineItems.push(obj);

                        let params = {
                            "OrganizationId": $scope.HospitalId,
                            "UserId": $scope.UserId,
                            "RenderingProviderId": $scope.mainClaimObject.VisitProviderId || null,
                            "OrganizationPayorId": $scope.PatientClaimTransmissionObj.OrganizationPayorId,
                            "PlanId": $scope.PatientClaimTransmissionObj.PlanId,
                            "ClaimLineItems": ClaimLineItems || []
                        }

                        console.log(params);

                        eHnoteInsuranceService.GetProcedurePayorPlanTypes(params).then(function (resp) {
                            console.log(resp);
                            if (resp.data.status == "Success") {
                                var PocedurePayorPlanTypes = resp.data.rows || [];


                                if (PocedurePayorPlanTypes.length > 0) {
                                    angular.forEach($scope.selectedLineItemObj.CostDetails, function (item) {
                                        let temparray = $filter("filter")(PocedurePayorPlanTypes, { "OrganizationProcedureId": item.OrganizationProcedureId }, true) || [];
                                        if (temparray.length > 0) {
                                            if ($scope.mainClaimObject.BillPaymentTypeId == 1) {
                                                item.UnitCharge = temparray[0].ActualCost || 0;
                                            }
                                            else if ($scope.mainClaimObject.BillPaymentTypeId == 2 && $scope.mainClaimObject.ClaimTypeId === 2) {
                                                item.UnitCharge = temparray[0].InFacilityActualCost || 0;
                                            }
                                            else if ($scope.mainClaimObject.BillPaymentTypeId == 2 && $scope.mainClaimObject.ClaimTypeId === 1) {
                                                item.UnitCharge = temparray[0].OfficeActualCost || 0;
                                            } else {
                                                item.UnitCharge = temparray[0].ActualCost || 0;
                                            }
                                            item.TotalChargeAmount = item.UnitCharge * item.Quantity;
                                        }
                                    });


                                }

                            } else {
                                alertify.error(resp.data.Message);
                            }
                        }, function (err) {

                        });
                    }

                    if (!lineitem.IsSecondaryChargeEdited) {
                        $scope.GetOrganizationPayorCPTCost();
                    }
                }
            });
            $scope.mCostInstanceAdd.result.then(function (resp) {
                console.log(resp);
                if (resp !== null) {
                    var originalUnitCharge = lineitem.UnitCharge || 0;
                    var enteredCharge = resp.SecondryChargeAmount || 0;

                    var isActuallyEdited = resp.isSecondarychargeEdited
                        && enteredCharge > 0
                        && enteredCharge !== originalUnitCharge;

                    if (isActuallyEdited) {
                        lineitem.IsSecondaryChargeEdited = true;
                        lineitem.Quantity = lineitem.Quantity || 1;
                        lineitem.SecondaryUnitCharge = enteredCharge;
                        lineitem.SecondaryTotalChargeAmount = lineitem.SecondaryUnitCharge * lineitem.Quantity;
                        angular.forEach(lineitem.ClaimInsuranceLineItems, function (pitem) {
                            if (pitem.InsuranceIdentifierId === 2) {
                                pitem.UnitCharge = lineitem.SecondaryUnitCharge || 0;
                                pitem.Quantity = lineitem.Quantity || 0;
                                pitem.TotalChargeAmount = lineitem.SecondaryTotalChargeAmount || 0;
                            }
                        });
                    } else {
                        lineitem.IsSecondaryChargeEdited = false;
                        lineitem.SecondaryUnitCharge = 0;
                        lineitem.SecondaryTotalChargeAmount = 0;
                        angular.forEach(lineitem.ClaimInsuranceLineItems, function (pitem) {
                            if (pitem.InsuranceIdentifierId === 2) {
                                pitem.UnitCharge = originalUnitCharge;
                                pitem.Quantity = lineitem.Quantity || 1;
                                pitem.TotalChargeAmount = originalUnitCharge * (lineitem.Quantity || 1);
                            }
                        });
                    }
                }

                var secondaryEditedClaimLineItems = $filter('filter')(mainobj.PatientClaimLineItems, { "IsSecondaryChargeEdited": true }, true) || [];
                mainobj.IsSecondaryChargeEditedClaim = false;
                if (secondaryEditedClaimLineItems.length > 0) {
                    mainobj.IsSecondaryChargeEditedClaim = true;
                   // $scope.IsSaveClaimTransactions = false;

                    angular.forEach($scope.mainClaimObject.PatientClaimLineItems, function (li) {
                        if (!li.IsSecondaryChargeEdited && li.ServiceId !== 0) {

                            angular.forEach(li.ClaimInsuranceLineItems, function (pitem) {

                                console.log(pitem.InsuranceIdentifierId + "__InsuranceIdentifierId");
                                if (pitem.InsuranceIdentifierId === 2) {

                                    console.log(pitem.UnitCharge + "__UnitCharge");
                                    // if (!pitem.UnitCharge || pitem.UnitCharge === 0) {

                                    pitem.UnitCharge = li.UnitCharge || 0;
                                    pitem.Quantity = li.Quantity || 1;
                                    pitem.TotalChargeAmount = (li.UnitCharge || 0) * (li.Quantity || 1);

                                    console.log(pitem.UnitCharge + "__UnitCharge" + pitem.Quantity + "__" + pitem.TotalChargeAmount);
                                    //}
                                }
                            });
                        }
                    });
                }


                console.log($scope.mainClaimObject.PatientClaimLineItems);

                if ($scope.IsSecondaryChargeEditInd && mainobj.IsSecondaryChargeEditedClaim) {
                    $scope.calculateLineItemInsuranceAmounts();
                } else {
                    $scope.calculateLineItemsAmount();
                }
            });
        };

        $scope.removeSecondaryCharge = function (lineitem) {

            lineitem.IsSecondaryChargeEdited = false;
            lineitem.SecondaryUnitCharge = 0;
            lineitem.SecondaryTotalChargeAmount = 0;
            var secondaryEditedClaimLineItems = $filter('filter')($scope.mainClaimObject.PatientClaimLineItems, { "IsSecondaryChargeEdited": true }, true) || [];

            $scope.mainClaimObject.IsSecondaryChargeEditedClaim = false;
            if (secondaryEditedClaimLineItems.length > 0) {
                $scope.mainClaimObject.IsSecondaryChargeEditedClaim = true;
            }
        }

